globalThis.DEClic_BUILTINS = [{"id": "marketing", "title": "Marketing", "description": "Définitions et notions essentielles du marketing.", "symbol": "M", "storageKey": "declic-marketing-concepts-v3", "cards": [{"id": "marketing-concept-001", "chapter": "Bases du marketing", "question": "Quelle est la définition du marketing ?", "answer": "Le marketing regroupe les activités qui permettent de comprendre les besoins et désirs, de concevoir une offre adaptée et de créer, communiquer et délivrer de la valeur. Il vise des relations durables avec les clients.", "sources": [{"documentId": "mf", "page": 1, "excerpt": "Définition 1 (démarche d'une entreprise) : démarche visant à créer de la valeur pour ses clients,\nà nouer des relations rentables avec eux, afin de bénéficier en retour de valeur.\nDéfinition 2 (ensemble d'activités) : ensemble d'activités d'une organisation visant à déterminer ou\nanticiper les besoins et désirs des clients et prospects, à élaborer une offre de produits ou de\nservices adaptée, en termes de prix, qualité, distribution, et à assurer la promotion de ces biens et\nservices.\nÀ retenir : le marketing s'adapte aux évolutions et propose des moyens de créer de la valeur pour les\nconsommateurs, les entreprises et les autres parties prenantes, afin d'avoir des échanges\néquitables.\n5. Pourquoi le marketing a évolué\nCôté\nRaison\nOffre (entreprises)\nRecherche d'outils performants pour satisfaire un maximum de clients et les", "highlight": "Définition 1"}]}, {"id": "marketing-concept-002", "chapter": "Bases du marketing", "question": "Qu’est-ce qu’un besoin ?", "answer": "Un besoin est un état de manque lié à la nature humaine. Il peut être physique, social ou individuel."}, {"id": "marketing-concept-003", "chapter": "Bases du marketing", "question": "Qu’est-ce qu’un désir ?", "answer": "Un désir est la forme précise que prend un besoin sous l’influence de la culture et de la personnalité."}, {"id": "marketing-concept-004", "chapter": "Bases du marketing", "question": "Qu’est-ce que la demande ?", "answer": "La demande correspond aux produits ou services que les consommateurs veulent et peuvent acheter, à un prix donné et pendant une période donnée."}, {"id": "marketing-concept-005", "chapter": "Bases du marketing", "question": "Quelle différence y a-t-il entre besoin, désir et demande ?", "answer": "Le besoin est un manque. Le désir est la réponse précise souhaitée. La demande suppose une volonté d’achat et un pouvoir d’achat suffisant."}, {"id": "marketing-concept-006", "chapter": "Bases du marketing", "question": "Quels sont les cinq niveaux de besoins de Maslow ?", "answer": "Besoins physiologiques, sécurité, appartenance, estime et accomplissement de soi."}, {"id": "marketing-concept-007", "chapter": "Bases du marketing", "question": "Quels sont les cinq types de besoins distingués par Kotler ?", "answer": "Besoins exprimés, réels, latents, rêvés et profonds. Ils correspondent à ce que le client dit, veut dire, n’envisage pas encore, rêve d’obtenir ou recherche plus secrètement."}, {"id": "marketing-concept-008", "chapter": "Bases du marketing", "question": "Qu’est-ce qu’une offre commerciale ?", "answer": "C’est un bien ou un service proposé sur un marché pour satisfaire un besoin ou un désir.", "sources": [{"documentId": "mf", "page": 4, "excerpt": "Tout ce qui peut être acquis sur un marché pour satisfaire un besoin (création de valeur) : bien\n(tangible) ou service (intangible), fruit de l'effort de l'entreprise en réponse aux besoins détectés.\n•\n3 dimensions : caractéristiques techniques, commerciales, psychologiques. Les consommateurs\ny sont plus ou moins sensibles ; l'entreprise doit réfléchir aux trois niveaux.\n•\nRôle de la marque : un bon produit sans marque forte n'est rien, et une marque forte sans bon\nproduit non plus. Le brand manager met en avant l'identité de la marque, ne cède pas aux actions de\ncourt terme et assure la cohérence de l'identité.\n•\nPackaging :\nFonctions techniques\nFonctions marketing\nProtection et conservation · facilité d'utilisation ·\ncommodité de transport et de stockage\nSource d'informations pratiques (origine, composition, date", "highlight": "Tout ce qui peut être acquis"}]}, {"id": "marketing-concept-009", "chapter": "Bases du marketing", "question": "Quelle est la différence entre un bien et un service ?", "answer": "Un bien est tangible, alors qu’un service est intangible.", "sources": [{"documentId": "mf", "page": 4, "excerpt": "Tout ce qui peut être acquis sur un marché pour satisfaire un besoin (création de valeur) : bien\n(tangible) ou service (intangible), fruit de l'effort de l'entreprise en réponse aux besoins détectés.\n•\n3 dimensions : caractéristiques techniques, commerciales, psychologiques. Les consommateurs\ny sont plus ou moins sensibles ; l'entreprise doit réfléchir aux trois niveaux.\n•\nRôle de la marque : un bon produit sans marque forte n'est rien, et une marque forte sans bon\nproduit non plus. Le brand manager met en avant l'identité de la marque, ne cède pas aux actions de\ncourt terme et assure la cohérence de l'identité.\n•\nPackaging :\nFonctions techniques\nFonctions marketing\nProtection et conservation · facilité d'utilisation ·\ncommodité de transport et de stockage\nSource d'informations pratiques (origine, composition, date\nlimite…) · reconnaissance et identification · expression du\npositionnement · impulsion d'achat\nLe prix\n•", "highlight": "bien\n(tangible)"}]}, {"id": "marketing-concept-010", "chapter": "Bases du marketing", "question": "Qu’est-ce que la myopie marketing ?", "answer": "C’est le fait de se concentrer sur le produit lui-même plutôt que sur les besoins, bénéfices ou expériences recherchés par les clients."}, {"id": "marketing-concept-011", "chapter": "Bases du marketing", "question": "Qu’est-ce que la valeur perçue ?", "answer": "C’est la différence entre les bénéfices perçus et les coûts perçus par le client. Elle est subjective."}, {"id": "marketing-concept-012", "chapter": "Bases du marketing", "question": "Qu’est-ce que la satisfaction du client ?", "answer": "Elle résulte de la comparaison entre les attentes du client et l’expérience qu’il a réellement vécue."}, {"id": "marketing-concept-013", "chapter": "Bases du marketing", "question": "Quelle est la différence entre un client et un prospect ?", "answer": "Un client a déjà acheté. Un prospect est un client potentiel qui n’a pas encore acheté."}, {"id": "marketing-concept-014", "chapter": "Bases du marketing", "question": "Que signifient B2C, B2B et C2C ?", "answer": "B2C : entreprise vers consommateur. B2B : entreprise vers entreprise. C2C : échanges entre consommateurs."}, {"id": "marketing-concept-015", "chapter": "Démarche et orientations", "question": "Quelles sont les trois phases de la démarche marketing ?", "answer": "Le marketing d’études, le marketing stratégique et le marketing opérationnel. Le contrôle permet de mesurer les résultats et de corriger les actions."}, {"id": "marketing-concept-016", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing d’études ?", "answer": "Il consiste à recueillir et analyser des informations sur le marché, l’entreprise et son environnement pour comprendre la situation."}, {"id": "marketing-concept-017", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing stratégique ?", "answer": "Il consiste notamment à choisir les segments à servir et à définir une offre et un positionnement adaptés.", "sources": [{"documentId": "mf", "page": 3, "excerpt": "3.3 La politique marketing en place\nPolitique produit ou marque (cf. marketing-mix). Regarder les dimensions stratégiques (objectifs,\nsegmentation, ciblage, positionnement) et opérationnelles (marketing-mix : produit, prix, distribution,\ncommunication).\n3.4 L'avantage concurrentiel\nLes stratégies génériques de Porter (détail non noté dans votre cours).\nRésultat : l'analyse de l'environnement interne identifie les forces et faiblesses.\n4. Conclusion : connaître, s'adapter, influencer\n•\nUne organisation doit chercher à s'adapter et à modifier l'environnement dans lequel elle évolue,\ndonc d'abord bien le connaître. Cette triple nécessité (connaître, s'adapter, influencer) fonde\nle marketing.\n•\nAnalyse interne = forces / faiblesses. Analyse externe = menaces / opportunités (c'est aussi un", "highlight": "3.3 La politique marketing en place"}]}, {"id": "marketing-concept-018", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing opérationnel ?", "answer": "Il met en œuvre les actions marketing autour du produit, du prix, de la distribution et de la communication.", "sources": [{"documentId": "mf", "page": 3, "excerpt": "3.3 La politique marketing en place\nPolitique produit ou marque (cf. marketing-mix). Regarder les dimensions stratégiques (objectifs,\nsegmentation, ciblage, positionnement) et opérationnelles (marketing-mix : produit, prix, distribution,\ncommunication).\n3.4 L'avantage concurrentiel\nLes stratégies génériques de Porter (détail non noté dans votre cours).\nRésultat : l'analyse de l'environnement interne identifie les forces et faiblesses.\n4. Conclusion : connaître, s'adapter, influencer\n•\nUne organisation doit chercher à s'adapter et à modifier l'environnement dans lequel elle évolue,\ndonc d'abord bien le connaître. Cette triple nécessité (connaître, s'adapter, influencer) fonde\nle marketing.\n•\nAnalyse interne = forces / faiblesses. Analyse externe = menaces / opportunités (c'est aussi un", "highlight": "3.3 La politique marketing en place"}]}, {"id": "marketing-concept-019", "chapter": "Démarche et orientations", "question": "Qu’est-ce qu’une étude documentaire ?", "answer": "C’est l’exploitation d’informations déjà disponibles. Elle est rapide et peu coûteuse, mais les données peuvent être trop générales ou peu adaptées."}, {"id": "marketing-concept-020", "chapter": "Démarche et orientations", "question": "Quelle différence y a-t-il entre une étude qualitative et une étude quantitative ?", "answer": "L’étude qualitative cherche à comprendre les motivations, notamment par des entretiens. L’étude quantitative mesure des phénomènes, notamment par des sondages."}, {"id": "marketing-concept-021", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation production ?", "answer": "Elle donne la priorité à la capacité de production, à la productivité, à la baisse des coûts et à la disponibilité des produits."}, {"id": "marketing-concept-022", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation produit ?", "answer": "Elle repose sur l’idée que le consommateur choisit le produit offrant la meilleure qualité ou les meilleures performances techniques."}, {"id": "marketing-concept-023", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation vente ?", "answer": "Elle consiste à chercher à faire accepter et acheter ce qui a été produit, grâce à la pression commerciale et publicitaire."}, {"id": "marketing-concept-024", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation marketing ?", "answer": "Elle part des besoins et attentes des consommateurs pour concevoir les produits et services susceptibles de les satisfaire."}, {"id": "marketing-concept-025", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing sociétal ?", "answer": "Il recherche un équilibre entre les désirs des consommateurs, les objectifs de l’entreprise et le bien-être collectif à long terme."}, {"id": "marketing-concept-026", "chapter": "Environnement", "question": "Qu’est-ce que le macro-environnement ?", "answer": "C’est l’ensemble des grandes forces externes que l’organisation ne contrôle pas directement mais auxquelles elle doit s’adapter."}, {"id": "marketing-concept-027", "chapter": "Environnement", "question": "Qu’est-ce que le micro-environnement ?", "answer": "Il est constitué des acteurs proches avec lesquels l’organisation interagit pour mener sa stratégie marketing."}, {"id": "marketing-concept-028", "chapter": "Environnement", "question": "Que signifie PESTEL ?", "answer": "Politique, économique, socioculturel, technologique, écologique et légal. Cet outil sert à analyser le macro-environnement."}, {"id": "marketing-concept-029", "chapter": "Environnement", "question": "Quels sont les principaux acteurs du micro-environnement ?", "answer": "Les acheteurs et consommateurs, les fournisseurs, les concurrents, les prescripteurs, les intermédiaires et les groupes d’influence."}, {"id": "marketing-concept-030", "chapter": "Environnement", "question": "Quelle différence y a-t-il entre un acheteur et un consommateur ?", "answer": "L’acheteur effectue l’achat ; le consommateur utilise le produit ou le service. Ce peut être la même personne ou deux personnes différentes.", "sources": [{"documentId": "mf", "page": 7, "excerpt": "consommation. Rôle dans le processus d'achat :\nacheteur, utilisateur, prescripteur ne sont pas la même\npersonne. Prix psychologique : prix que le\nconsommateur est prêt à payer, où le rapport qualité-prix\nest acceptable\nPsychographiques\nPersonnalité : réponses stables d'un individu dans son\nenvironnement. Valeurs : croyances durables selon\nlesquelles certains comportements ou buts de l'existence\nsont préférables ; varient selon l'individu et la culture.\nStyles de vie : manière d'occuper son temps, ce qu'on\njuge important, ce qu'on pense de soi et du monde ;\nrésultat probable de l'interaction entre valeurs et\npersonnalité\nSegmentation RFM : la rubrique est vide dans vos notes. RFM correspond habituellement à récence,\nfréquence, montant d'achat : à compléter avec votre cours.\n1.4 Segmenter la demande en B2B", "highlight": "Rôle dans le processus d'achat"}]}, {"id": "marketing-concept-031", "chapter": "Environnement", "question": "Qu’est-ce qu’un prescripteur ?", "answer": "C’est une personne ou une organisation qui influence la décision d’achat par ses conseils ou recommandations, sans nécessairement acheter."}, {"id": "marketing-concept-032", "chapter": "Environnement", "question": "Quelle différence y a-t-il entre concurrence directe et indirecte ?", "answer": "La concurrence directe propose des produits ou services identiques ou très proches. La concurrence indirecte propose des solutions différentes répondant au même besoin."}, {"id": "marketing-concept-033", "chapter": "Environnement", "question": "Qu’est-ce qu’un monopole ?", "answer": "C’est une structure de marché dans laquelle une seule entreprise propose l’offre considérée."}, {"id": "marketing-concept-034", "chapter": "Environnement", "question": "Qu’est-ce qu’un oligopole ?", "answer": "C’est une structure de marché dans laquelle quelques entreprises se partagent l’offre."}, {"id": "marketing-concept-035", "chapter": "Environnement", "question": "Quelles sont les cinq forces de Porter ?", "answer": "La rivalité entre concurrents, la menace des nouveaux entrants, la menace des substituts, le pouvoir de négociation des fournisseurs et le pouvoir de négociation des clients."}, {"id": "marketing-concept-036", "chapter": "Environnement", "question": "Qu’est-ce qu’une tendance de marché ?", "answer": "C’est une évolution durable des comportements, attentes ou technologies qui influence l’offre et la demande."}, {"id": "marketing-concept-037", "chapter": "Marché", "question": "Quelle est la définition d’un marché ?", "answer": "Un marché est le lieu de rencontre entre l’offre et la demande permettant des transactions. Il peut être physique ou virtuel."}, {"id": "marketing-concept-038", "chapter": "Marché", "question": "Quelle différence y a-t-il entre un marché atomisé et un marché concentré ?", "answer": "Un marché atomisé est partagé entre de nombreux acteurs. Un marché concentré compte peu d’entreprises qui occupent une place importante."}, {"id": "marketing-concept-039", "chapter": "Marché", "question": "Qu’est-ce que le marché principal ?", "answer": "Il regroupe les produits techniquement identiques et directement concurrents."}, {"id": "marketing-concept-040", "chapter": "Marché", "question": "Qu’est-ce que le marché environnant ?", "answer": "Il regroupe les produits de nature différente qui peuvent se substituer aux produits du marché principal pour satisfaire le même besoin."}, {"id": "marketing-concept-041", "chapter": "Marché", "question": "Qu’est-ce que le marché générique ?", "answer": "Il regroupe les produits liés à la catégorie générale de besoins satisfaite par les produits du marché principal."}, {"id": "marketing-concept-042", "chapter": "Marché", "question": "Qu’est-ce que le marché support ?", "answer": "Il regroupe les produits associés ou complémentaires à la consommation des produits considérés."}, {"id": "marketing-concept-043", "chapter": "Marché", "question": "Qu’est-ce que le marché réel ?", "answer": "Il correspond aux consommateurs qui ont acheté le produit pendant une période donnée."}, {"id": "marketing-concept-044", "chapter": "Marché", "question": "Qu’est-ce que le marché potentiel ?", "answer": "Il rassemble les consommateurs actuels et les non-consommateurs relatifs."}, {"id": "marketing-concept-045", "chapter": "Marché", "question": "Quelle différence y a-t-il entre un non-consommateur relatif et un non-consommateur absolu ?", "answer": "Le non-consommateur relatif pourrait devenir consommateur. Le non-consommateur absolu ne peut pas ou ne veut durablement pas consommer le produit dans le cadre étudié."}, {"id": "marketing-concept-046", "chapter": "Marché", "question": "Quelle différence y a-t-il entre un marché en volume et un marché en valeur ?", "answer": "Le volume mesure les quantités physiques vendues. La valeur mesure le montant monétaire des ventes."}, {"id": "marketing-concept-047", "chapter": "Marché", "question": "Comment calcule-t-on le taux de croissance d’un marché ?", "answer": "Taux de croissance (%) = (valeur d’arrivée - valeur de départ) / valeur de départ × 100."}, {"id": "marketing-concept-048", "chapter": "Marché", "question": "Comment calcule-t-on une part de marché absolue ?", "answer": "Part de marché (%) = ventes de l’entreprise / ventes totales du marché × 100. Le calcul peut se faire en volume ou en valeur.", "sources": [{"documentId": "mf", "page": 2, "excerpt": "Part de marché absolue (PDM) = ventes de l'entreprise ÷ ventes du marché × 100.\n•\nPart de marché relative = PDM de l'entreprise ÷ PDM du 1er concurrent. Elle indique la position\nconcurrentielle : elle mesure la distance entre une marque et le leader. Une PDM relative supérieure\nà 1 (ex. 1,1) signifie que l'entreprise domine le marché.\n•\nTaux de pénétration = marché réel rapporté au marché potentiel (nombre d'abonnements ÷\npopulation totale de référence). Un taux bas signifie un potentiel de croissance élevé pour toutes\nles entreprises du marché. Exemple : mobiles en France, de 40 % en juin 2000 à plus de 91 % en 2009.\nExercice Duplay (CA en M€)\nProduit\nCA Duplay\nCA principal concurrent\nCA du secteur\nPDM absolue\nPDM relative\nSaxophone\n7,5\n2,5\n30,5\n24,6 %\n3\nTrompette\n1,5\n3\n6\n25 %\n0,50\nCor de chasse\n1\n4\n11\n9,09 %\n0,25\nAccordéon\n1\n3\n13,5", "highlight": "Part de marché absolue"}]}, {"id": "marketing-concept-049", "chapter": "Marché", "question": "Comment calcule-t-on une part de marché relative ?", "answer": "Part de marché relative = part de marché de l’entreprise / part de marché de son principal concurrent. C’est un ratio.", "sources": [{"documentId": "mf", "page": 2, "excerpt": "Part de marché relative = PDM de l'entreprise ÷ PDM du 1er concurrent. Elle indique la position\nconcurrentielle : elle mesure la distance entre une marque et le leader. Une PDM relative supérieure\nà 1 (ex. 1,1) signifie que l'entreprise domine le marché.\n•\nTaux de pénétration = marché réel rapporté au marché potentiel (nombre d'abonnements ÷\npopulation totale de référence). Un taux bas signifie un potentiel de croissance élevé pour toutes\nles entreprises du marché. Exemple : mobiles en France, de 40 % en juin 2000 à plus de 91 % en 2009.\nExercice Duplay (CA en M€)\nProduit\nCA Duplay\nCA principal concurrent\nCA du secteur\nPDM absolue\nPDM relative\nSaxophone\n7,5\n2,5\n30,5\n24,6 %\n3\nTrompette\n1,5\n3\n6\n25 %\n0,50\nCor de chasse\n1\n4\n11\n9,09 %\n0,25\nAccordéon\n1\n3\n13,5\n7,41 %\n0,33\nHarmonica\n3\n1,5\n8,5\n35,29 %\n2\nSynthétiseur\n1\n4\n13\n7,69 %\n0,25", "highlight": "Part de marché relative"}]}, {"id": "marketing-concept-050", "chapter": "Marché", "question": "Comment interprète-t-on une part de marché relative ?", "answer": "Supérieure à 1 : l’entreprise dépasse son principal concurrent. Égale à 1 : elles réalisent les mêmes ventes. Inférieure à 1 : l’entreprise est derrière.", "sources": [{"documentId": "mf", "page": 2, "excerpt": "Part de marché relative = PDM de l'entreprise ÷ PDM du 1er concurrent. Elle indique la position\nconcurrentielle : elle mesure la distance entre une marque et le leader. Une PDM relative supérieure\nà 1 (ex. 1,1) signifie que l'entreprise domine le marché.\n•\nTaux de pénétration = marché réel rapporté au marché potentiel (nombre d'abonnements ÷\npopulation totale de référence). Un taux bas signifie un potentiel de croissance élevé pour toutes\nles entreprises du marché. Exemple : mobiles en France, de 40 % en juin 2000 à plus de 91 % en 2009.\nExercice Duplay (CA en M€)\nProduit\nCA Duplay\nCA principal concurrent\nCA du secteur\nPDM absolue\nPDM relative\nSaxophone\n7,5\n2,5\n30,5\n24,6 %\n3\nTrompette\n1,5\n3\n6\n25 %\n0,50\nCor de chasse\n1\n4\n11\n9,09 %\n0,25\nAccordéon\n1\n3\n13,5\n7,41 %\n0,33\nHarmonica\n3\n1,5\n8,5\n35,29 %\n2\nSynthétiseur\n1\n4\n13\n7,69 %\n0,25", "highlight": "Part de marché relative"}]}, {"id": "marketing-concept-051", "chapter": "Marché", "question": "Comment calcule-t-on le taux de pénétration ?", "answer": "Taux de pénétration (%) = marché réel / marché potentiel × 100.", "sources": [{"documentId": "mf", "page": 2, "excerpt": "Taux de pénétration = marché réel rapporté au marché potentiel (nombre d'abonnements ÷\npopulation totale de référence). Un taux bas signifie un potentiel de croissance élevé pour toutes\nles entreprises du marché. Exemple : mobiles en France, de 40 % en juin 2000 à plus de 91 % en 2009.\nExercice Duplay (CA en M€)\nProduit\nCA Duplay\nCA principal concurrent\nCA du secteur\nPDM absolue\nPDM relative\nSaxophone\n7,5\n2,5\n30,5\n24,6 %\n3\nTrompette\n1,5\n3\n6\n25 %\n0,50\nCor de chasse\n1\n4\n11\n9,09 %\n0,25\nAccordéon\n1\n3\n13,5\n7,41 %\n0,33\nHarmonica\n3\n1,5\n8,5\n35,29 %\n2\nSynthétiseur\n1\n4\n13\n7,69 %\n0,25\nConclusion : Duplay est leader (PDM relative supérieure à 1) sur le saxophone et l'harmonica.\n2. Le cycle de vie\n•\nLes marchés évoluent en 4 phases : naissance, croissance, maturité, déclin.\n•", "highlight": "Taux de pénétration"}]}, {"id": "marketing-concept-052", "chapter": "Marché", "question": "Quelles sont les quatre phases du cycle de vie d’un marché ?", "answer": "Naissance, croissance, maturité et déclin.", "sources": [{"documentId": "mf", "page": 2, "excerpt": "2. Le cycle de vie\n•\nLes marchés évoluent en 4 phases : naissance, croissance, maturité, déclin.\n•\nLes phases du cycle de vie d'un marché ne doivent pas être confondues avec celles du produit. Ex. :\nle marché de l'automobile peut être mature alors que le véhicule électrique est en phase de\ncroissance.\n3. L'environnement interne de l'organisation\nAnalyse interne : diagnostic systématique des caractéristiques propres à l'organisation (ressources,\nfonctionnement, compétences, politique marketing).\nObjectifs : évaluer les atouts · détecter les limites ou dysfonctionnements qui freinent la performance ·\npréparer la matrice SWOT.\nChaîne de valeur (Porter) : identifie les activités clés qui créent de la valeur et analyse les coûts ; elle\npeut servir de base à l'analyse interne.\n3.1 Les ressources internes (ce que l'organisation peut mobiliser)", "highlight": "2. Le cycle de vie"}]}, {"id": "marketing-concept-053", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce qu’une analyse interne ?", "answer": "C’est l’analyse des ressources, compétences, fonctionnement et politique marketing de l’organisation pour identifier ses forces et ses faiblesses.", "sources": [{"documentId": "mf", "page": 2, "excerpt": "Analyse interne : diagnostic systématique des caractéristiques propres à l'organisation (ressources,\nfonctionnement, compétences, politique marketing).\nObjectifs : évaluer les atouts · détecter les limites ou dysfonctionnements qui freinent la performance ·\npréparer la matrice SWOT.\nChaîne de valeur (Porter) : identifie les activités clés qui créent de la valeur et analyse les coûts ; elle\npeut servir de base à l'analyse interne.\n3.1 Les ressources internes (ce que l'organisation peut mobiliser)\nType\nExemples\nMatérielles et financières\nQualité, quantité et modernité des équipements, business model, capacité\nd'investissement\nImmatérielles\nSavoir-faire, brevets, innovations, certifications, engagements, réseau de", "highlight": "Analyse interne :"}]}, {"id": "marketing-concept-054", "chapter": "Diagnostic et stratégie", "question": "À quoi sert la chaîne de valeur de Porter ?", "answer": "Elle identifie les activités qui créent de la valeur et permet d’en analyser les coûts.", "sources": [{"documentId": "mf", "page": 2, "excerpt": "Chaîne de valeur (Porter) : identifie les activités clés qui créent de la valeur et analyse les coûts ; elle\npeut servir de base à l'analyse interne.\n3.1 Les ressources internes (ce que l'organisation peut mobiliser)\nType\nExemples\nMatérielles et financières\nQualité, quantité et modernité des équipements, business model, capacité\nd'investissement\nImmatérielles\nSavoir-faire, brevets, innovations, certifications, engagements, réseau de", "highlight": "Chaîne de valeur (Porter)"}]}, {"id": "marketing-concept-055", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce que la notoriété d’une marque ?", "answer": "C’est le degré de connaissance d’une marque et de sa catégorie de produits par le public.", "sources": [{"documentId": "mf", "page": 3, "excerpt": "3.2 Notoriété et image\nElles influencent les clients actuels et les prospects (satisfaction, fidélisation) ; d'autres acteurs peuvent\naussi les influencer.\nType de notoriété\nDéfinition\nSpontanée\n% d'individus qui citent la marque sans aide\nTop of mind\n% d'individus qui citent la marque en 1re réponse\nAssistée\n% d'individus qui reconnaissent la marque à partir d'une liste proposée\nVos notes ajoutent une mesure : % d'individus qui connaissent la marque et la catégorie de produits à\nlaquelle elle appartient.\n3.3 La politique marketing en place\nPolitique produit ou marque (cf. marketing-mix). Regarder les dimensions stratégiques (objectifs,\nsegmentation, ciblage, positionnement) et opérationnelles (marketing-mix : produit, prix, distribution,\ncommunication).\n3.4 L'avantage concurrentiel", "highlight": "3.2 Notoriété et image"}]}, {"id": "marketing-concept-056", "chapter": "Diagnostic et stratégie", "question": "Quelle différence y a-t-il entre notoriété spontanée, top of mind et notoriété assistée ?", "answer": "Spontanée : la marque est citée sans aide. Top of mind : elle est citée en premier. Assistée : elle est reconnue à partir d’une liste.", "sources": [{"documentId": "mf", "page": 3, "excerpt": "Spontanée\n% d'individus qui citent la marque sans aide\nTop of mind\n% d'individus qui citent la marque en 1re réponse\nAssistée\n% d'individus qui reconnaissent la marque à partir d'une liste proposée\nVos notes ajoutent une mesure : % d'individus qui connaissent la marque et la catégorie de produits à\nlaquelle elle appartient.\n3.3 La politique marketing en place\nPolitique produit ou marque (cf. marketing-mix). Regarder les dimensions stratégiques (objectifs,\nsegmentation, ciblage, positionnement) et opérationnelles (marketing-mix : produit, prix, distribution,\ncommunication).\n3.4 L'avantage concurrentiel\nLes stratégies génériques de Porter (détail non noté dans votre cours).\nRésultat : l'analyse de l'environnement interne identifie les forces et faiblesses.\n4. Conclusion : connaître, s'adapter, influencer\n•", "highlight": "Spontanée"}]}, {"id": "marketing-concept-057", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce que l’image de marque ?", "answer": "C’est l’ensemble des représentations et associations que les consommateurs attachent à une marque."}, {"id": "marketing-concept-058", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les stratégies génériques de Porter ?", "answer": "La domination par les coûts, la différenciation et la concentration ou focalisation."}, {"id": "marketing-concept-059", "chapter": "Diagnostic et stratégie", "question": "Que signifie SWOT ?", "answer": "Strengths, Weaknesses, Opportunities, Threats : forces, faiblesses, opportunités et menaces.", "sources": [{"documentId": "mf", "page": 3, "excerpt": "Étape 1 : analyse de la situation (diagnostic stratégique = SWOT)\nPositifs / favorables\nNégatifs / défavorables\nFacteurs\ninternes\nForces : capacités internes qui aident à\natteindre les objectifs (ex. notoriété, innovation)\nFaiblesses : limites internes qui empêchent\nd'atteindre les objectifs (ex. manque de\nreconnaissance de la marque)\nFacteurs\nexternes\nOpportunités : facteurs externes à exploiter\n(ex. émergence du numérique, nouvelles\nhabitudes)\nMenaces : facteurs externes qui nuisent à la\nperformance (ex. produit facile à copier)\nObjectifs de l'analyse : combler les faiblesses · développer les forces · identifier et anticiper les\nmenaces · faire correspondre forces et opportunités · éliminer ou surmonter les menaces.\nQuestions du diagnostic : les forces compensent-elles les faiblesses ? Permettent-elles d'envisager", "highlight": "Étape 1 : analyse de la situation"}]}, {"id": "marketing-concept-060", "chapter": "Diagnostic et stratégie", "question": "Quelle différence y a-t-il entre les éléments internes et externes du SWOT ?", "answer": "Les forces et faiblesses sont internes à l’organisation. Les opportunités et menaces viennent de l’environnement externe.", "sources": [{"documentId": "mf", "page": 3, "excerpt": "Étape 1 : analyse de la situation (diagnostic stratégique = SWOT)\nPositifs / favorables\nNégatifs / défavorables\nFacteurs\ninternes\nForces : capacités internes qui aident à\natteindre les objectifs (ex. notoriété, innovation)\nFaiblesses : limites internes qui empêchent\nd'atteindre les objectifs (ex. manque de\nreconnaissance de la marque)\nFacteurs\nexternes\nOpportunités : facteurs externes à exploiter\n(ex. émergence du numérique, nouvelles\nhabitudes)\nMenaces : facteurs externes qui nuisent à la\nperformance (ex. produit facile à copier)\nObjectifs de l'analyse : combler les faiblesses · développer les forces · identifier et anticiper les\nmenaces · faire correspondre forces et opportunités · éliminer ou surmonter les menaces.\nQuestions du diagnostic : les forces compensent-elles les faiblesses ? Permettent-elles d'envisager", "highlight": "Étape 1 : analyse de la situation"}]}, {"id": "marketing-concept-061", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les quatre fonctions du pilotage marketing ?", "answer": "Analyse, planification, implémentation et contrôle. La démarche est itérative.", "sources": [{"documentId": "mf", "page": 3, "excerpt": "1. La stratégie marketing\nDémarche planifiée, mise en œuvre, contrôlée et analysée. Démarche globale itérative, en 4\nfonctions : analyse → planification → implémentation → contrôle.\nÉtape 1 : analyse de la situation (diagnostic stratégique = SWOT)\nPositifs / favorables\nNégatifs / défavorables\nFacteurs\ninternes\nForces : capacités internes qui aident à\natteindre les objectifs (ex. notoriété, innovation)\nFaiblesses : limites internes qui empêchent\nd'atteindre les objectifs (ex. manque de\nreconnaissance de la marque)\nFacteurs\nexternes\nOpportunités : facteurs externes à exploiter\n(ex. émergence du numérique, nouvelles\nhabitudes)\nMenaces : facteurs externes qui nuisent à la\nperformance (ex. produit facile à copier)\nObjectifs de l'analyse : combler les faiblesses · développer les forces · identifier et anticiper les", "highlight": "1. La stratégie marketing"}]}, {"id": "marketing-concept-062", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce que l’implémentation marketing ?", "answer": "C’est la mise en œuvre concrète de la stratégie prévue dans le plan marketing : qui agit, où, quand et comment.", "sources": [{"documentId": "mf", "page": 4, "excerpt": "Étape 3 : l'implémentation\nMettre en œuvre la stratégie décrite, par des actions concrètes.\nÉtape 4 : le contrôle marketing\nContrôle constant des actions, en 3 temps : mesurer les performances · évaluer l'écart entre\nperformances réalisées et attendues · mettre en place des actions correctrices pour réduire cet\nécart.\n2. Le marketing-mix\nDéfinition : ensemble des outils à la disposition de l'entreprise pour atteindre ses objectifs auprès du\nmarché visé.\nLe produit\n•\nTout ce qui peut être acquis sur un marché pour satisfaire un besoin (création de valeur) : bien\n(tangible) ou service (intangible), fruit de l'effort de l'entreprise en réponse aux besoins détectés.\n•\n3 dimensions : caractéristiques techniques, commerciales, psychologiques. Les consommateurs\ny sont plus ou moins sensibles ; l'entreprise doit réfléchir aux trois niveaux.\n•", "highlight": "Étape 3 : l'implémentation"}]}, {"id": "marketing-concept-063", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les trois étapes du contrôle marketing ?", "answer": "Mesurer les performances, comparer les résultats aux objectifs, puis mettre en place des actions correctrices.", "sources": [{"documentId": "mf", "page": 4, "excerpt": "Étape 4 : le contrôle marketing\nContrôle constant des actions, en 3 temps : mesurer les performances · évaluer l'écart entre\nperformances réalisées et attendues · mettre en place des actions correctrices pour réduire cet\nécart.\n2. Le marketing-mix\nDéfinition : ensemble des outils à la disposition de l'entreprise pour atteindre ses objectifs auprès du\nmarché visé.\nLe produit\n•\nTout ce qui peut être acquis sur un marché pour satisfaire un besoin (création de valeur) : bien\n(tangible) ou service (intangible), fruit de l'effort de l'entreprise en réponse aux besoins détectés.\n•\n3 dimensions : caractéristiques techniques, commerciales, psychologiques. Les consommateurs\ny sont plus ou moins sensibles ; l'entreprise doit réfléchir aux trois niveaux.\n•\nRôle de la marque : un bon produit sans marque forte n'est rien, et une marque forte sans bon", "highlight": "Étape 4 : le contrôle marketing"}]}, {"id": "marketing-concept-064", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les quatre stratégies de croissance d’Ansoff ?", "answer": "Pénétration de marché : produits et marchés existants. Développement de marché : produits existants et nouveaux marchés. Développement de produits : nouveaux produits et marchés existants. Diversification : nouveaux produits et nouveaux marchés.", "sources": [{"documentId": "mf", "page": 4, "excerpt": "Matrice d'Ansoff :\nProduits actuels\nProduits nouveaux\nMarchés\nactuels\n1. Pénétration du marché : développer les\nventes des produits existants sur les marchés\nactuels (attirer, convaincre, accroître)\n3. Développement de produits\nMarchés\nnouveaux\n2. Développement / extension de marché :\nproduits actuels sur de nouveaux marchés\n4. Diversification : nouveaux produits pour de\nnouveaux marchés\nÉtape 3 : l'implémentation\nMettre en œuvre la stratégie décrite, par des actions concrètes.\nÉtape 4 : le contrôle marketing\nContrôle constant des actions, en 3 temps : mesurer les performances · évaluer l'écart entre\nperformances réalisées et attendues · mettre en place des actions correctrices pour réduire cet\nécart.\n2. Le marketing-mix\nDéfinition : ensemble des outils à la disposition de l'entreprise pour atteindre ses objectifs auprès du\nmarché visé.", "highlight": "Matrice d'Ansoff"}]}, {"id": "marketing-concept-065", "chapter": "Marketing mix", "question": "Qu’est-ce que le marketing mix ?", "answer": "C’est l’ensemble cohérent des outils dont dispose l’entreprise pour atteindre ses objectifs sur le marché visé.", "sources": [{"documentId": "mf", "page": 4, "excerpt": "2. Le marketing-mix\nDéfinition : ensemble des outils à la disposition de l'entreprise pour atteindre ses objectifs auprès du\nmarché visé.\nLe produit\n•\nTout ce qui peut être acquis sur un marché pour satisfaire un besoin (création de valeur) : bien\n(tangible) ou service (intangible), fruit de l'effort de l'entreprise en réponse aux besoins détectés.\n•\n3 dimensions : caractéristiques techniques, commerciales, psychologiques. Les consommateurs\ny sont plus ou moins sensibles ; l'entreprise doit réfléchir aux trois niveaux.\n•\nRôle de la marque : un bon produit sans marque forte n'est rien, et une marque forte sans bon\nproduit non plus. Le brand manager met en avant l'identité de la marque, ne cède pas aux actions de\ncourt terme et assure la cohérence de l'identité.\n•\nPackaging :\nFonctions techniques\nFonctions marketing", "highlight": "2. Le marketing-mix"}]}, {"id": "marketing-concept-066", "chapter": "Marketing mix", "question": "Quels sont les 4P ?", "answer": "Product : produit. Price : prix. Place : distribution. Promotion : communication.", "sources": [{"documentId": "mf", "page": 3, "excerpt": "segmentation, ciblage, positionnement) et opérationnelles (marketing-mix : produit, prix, distribution,\ncommunication).\n3.4 L'avantage concurrentiel\nLes stratégies génériques de Porter (détail non noté dans votre cours).\nRésultat : l'analyse de l'environnement interne identifie les forces et faiblesses.\n4. Conclusion : connaître, s'adapter, influencer\n•\nUne organisation doit chercher à s'adapter et à modifier l'environnement dans lequel elle évolue,\ndonc d'abord bien le connaître. Cette triple nécessité (connaître, s'adapter, influencer) fonde\nle marketing.\n•\nAnalyse interne = forces / faiblesses. Analyse externe = menaces / opportunités (c'est aussi un\nétat d'esprit : une menace peut être une opportunité pour une organisation avisée).\n•\nAnalyse interne + analyse externe = diagnostic stratégique (SWOT).\nStratégie marketing et marketing-mix\n1. La stratégie marketing", "highlight": "marketing-mix : produit, prix, distribution"}]}, {"id": "marketing-concept-067", "chapter": "Marketing mix", "question": "Quelles sont les trois dimensions du produit ?", "answer": "Les caractéristiques techniques, commerciales et psychologiques.", "sources": [{"documentId": "mf", "page": 4, "excerpt": "3 dimensions : caractéristiques techniques, commerciales, psychologiques. Les consommateurs\ny sont plus ou moins sensibles ; l'entreprise doit réfléchir aux trois niveaux.\n•\nRôle de la marque : un bon produit sans marque forte n'est rien, et une marque forte sans bon\nproduit non plus. Le brand manager met en avant l'identité de la marque, ne cède pas aux actions de\ncourt terme et assure la cohérence de l'identité.\n•\nPackaging :\nFonctions techniques\nFonctions marketing\nProtection et conservation · facilité d'utilisation ·\ncommodité de transport et de stockage\nSource d'informations pratiques (origine, composition, date\nlimite…) · reconnaissance et identification · expression du\npositionnement · impulsion d'achat\nLe prix\n•\nFixé par l'entreprise, il se situe entre le coût de production et la valeur du produit aux yeux du\nclient.\n•", "highlight": "3 dimensions :"}]}, {"id": "marketing-concept-068", "chapter": "Marketing mix", "question": "Quelle différence y a-t-il entre produit intrinsèque, standard et global ?", "answer": "Le produit intrinsèque réunit les caractéristiques fondamentales. Le produit standard comprend sa présentation commerciale et sa marque. Le produit global ajoute les services associés, comme la garantie et le SAV."}, {"id": "marketing-concept-069", "chapter": "Marketing mix", "question": "Qu’est-ce que le capital marque ?", "answer": "C’est l’effet de la connaissance de la marque sur la manière dont les consommateurs réagissent à son marketing."}, {"id": "marketing-concept-070", "chapter": "Marketing mix", "question": "Quelles sont les fonctions du packaging ?", "answer": "Fonctions techniques : protéger, conserver et faciliter l’utilisation, le transport et le stockage. Fonctions marketing : informer, identifier le produit, exprimer le positionnement et favoriser l’achat.", "sources": [{"documentId": "mf", "page": 4, "excerpt": "Packaging :\nFonctions techniques\nFonctions marketing\nProtection et conservation · facilité d'utilisation ·\ncommodité de transport et de stockage\nSource d'informations pratiques (origine, composition, date\nlimite…) · reconnaissance et identification · expression du\npositionnement · impulsion d'achat\nLe prix\n•\nFixé par l'entreprise, il se situe entre le coût de production et la valeur du produit aux yeux du\nclient.\n•\nLes stratégies de tarification d'un nouveau produit varient selon les phases du cycle de vie. Au\nlancement, il existe 2 approches (non détaillées dans vos notes).\nSéquence 4 – Segmentation, ciblage et positionnement\nLes entreprises ne cherchent pas à satisfaire tous les clients d'un marché, car leurs désirs, ressources et\ncomportements diffèrent. Elles ciblent donc ceux qui s'intéressent le plus à leur proposition de valeur,", "highlight": "Packaging :"}]}, {"id": "marketing-concept-071", "chapter": "Marketing mix", "question": "Quels facteurs influencent la fixation du prix ?", "answer": "Les coûts, la demande et la valeur perçue, les prix des concurrents, les objectifs de l’organisation, les contraintes légales et les tests de prix.", "sources": [{"documentId": "mf", "page": 4, "excerpt": "Le prix\n•\nFixé par l'entreprise, il se situe entre le coût de production et la valeur du produit aux yeux du\nclient.\n•\nLes stratégies de tarification d'un nouveau produit varient selon les phases du cycle de vie. Au\nlancement, il existe 2 approches (non détaillées dans vos notes).\nSéquence 4 – Segmentation, ciblage et positionnement\nLes entreprises ne cherchent pas à satisfaire tous les clients d'un marché, car leurs désirs, ressources et\ncomportements diffèrent. Elles ciblent donc ceux qui s'intéressent le plus à leur proposition de valeur,", "highlight": "Le prix"}]}, {"id": "marketing-concept-072", "chapter": "Marketing mix", "question": "Qu’est-ce qu’une politique d’écrémage ?", "answer": "C’est une politique de lancement à prix élevé, destinée aux consommateurs les plus intéressés et solvables."}, {"id": "marketing-concept-073", "chapter": "Marketing mix", "question": "Qu’est-ce qu’une politique de pénétration tarifaire ?", "answer": "C’est une politique de lancement à prix bas pour attirer rapidement de nombreux acheteurs et gagner une part de marché importante."}, {"id": "marketing-concept-074", "chapter": "Marketing mix", "question": "Qu’est-ce que la distribution ?", "answer": "C’est l’ensemble des choix et actions qui rendent le produit ou service accessible au consommateur final."}, {"id": "marketing-concept-075", "chapter": "Marketing mix", "question": "Qu’est-ce qu’un circuit de distribution direct ?", "answer": "C’est un circuit dans lequel le producteur vend directement au consommateur, sans intermédiaire."}, {"id": "marketing-concept-076", "chapter": "Marketing mix", "question": "Qu’est-ce que la distribution multicanale ?", "answer": "C’est l’utilisation de plusieurs canaux de distribution pour rendre l’offre accessible aux clients."}, {"id": "marketing-concept-077", "chapter": "Marketing mix", "question": "Quelle différence y a-t-il entre communication interne et externe ?", "answer": "La communication interne s’adresse aux membres de l’organisation. La communication externe s’adresse aux publics extérieurs, notamment aux clients et prospects."}, {"id": "marketing-concept-078", "chapter": "Marketing mix", "question": "Quels sont les trois objectifs de communication ?", "answer": "Cognitif : faire connaître. Affectif : faire aimer. Conatif : faire agir."}, {"id": "marketing-concept-079", "chapter": "Marketing mix", "question": "Que signifie le modèle POEM ?", "answer": "Paid : médias payants. Owned : supports maîtrisés par la marque. Earned : visibilité obtenue auprès de tiers."}, {"id": "marketing-concept-080", "chapter": "Marketing mix", "question": "Qu’est-ce que le greenwashing ?", "answer": "C’est l’utilisation trompeuse ou opportuniste d’arguments environnementaux pour donner une image plus responsable que les pratiques réelles."}, {"id": "marketing-concept-081", "chapter": "Segmentation", "question": "Quelle est la définition de la segmentation ?", "answer": "La segmentation consiste à découper un marché en groupes de consommateurs qui partagent des besoins, caractéristiques ou comportements communs.", "sources": [{"documentId": "mf", "page": 5, "excerpt": "Segmenter : découper le marché en groupes d'individus partageant des besoins, caractéristiques ou\ncomportements communs.\nCritère\nQuestion\nExemples\nGéographique\nOù habite-t-il ? Où achète-t-il ?\nPays, régions, villes ; habitat rural/urbain ; climat\nSocio-démographique\nQui est-il ?\nÂge, sexe, revenu, composition du foyer, CSP, niveau\nd'étude\nPsychographique\nQue pense-t-il ?\nStyle de vie, personnalité, valeurs, motivations\nAvantages recherchés\nPourquoi achète-t-il ?\nProduits pas chers, produits santé\nComportemental\nQue fait-il ?\nComportements réels et observables\nPhysique\nTaille, corpulence, couleur de cheveux ou de peau\nDétail des critères\n•\nGéographique : unités territoriales, type d'habitat, climat ; l'implantation se limite à un secteur.", "highlight": "Segmenter :"}]}, {"id": "marketing-concept-082", "chapter": "Segmentation", "question": "Quels sont les principaux critères de segmentation ?", "answer": "Critères géographiques, sociodémographiques, psychographiques, avantages recherchés, comportements et caractéristiques physiques.", "sources": [{"documentId": "mf", "page": 5, "excerpt": "Critère\nQuestion\nExemples\nGéographique\nOù habite-t-il ? Où achète-t-il ?\nPays, régions, villes ; habitat rural/urbain ; climat\nSocio-démographique\nQui est-il ?\nÂge, sexe, revenu, composition du foyer, CSP, niveau\nd'étude\nPsychographique\nQue pense-t-il ?\nStyle de vie, personnalité, valeurs, motivations\nAvantages recherchés\nPourquoi achète-t-il ?\nProduits pas chers, produits santé\nComportemental\nQue fait-il ?\nComportements réels et observables\nPhysique\nTaille, corpulence, couleur de cheveux ou de peau\nDétail des critères\n•\nGéographique : unités territoriales, type d'habitat, climat ; l'implantation se limite à un secteur.\nExemples : Sorel (chaussures de ski), Dasani (eau purifiée). Marketing localisé : adapte l'offre à une\nclientèle. Marketing personnalisé ou one to one : différencie partiellement l'offre (conditions", "highlight": "Critère\nQuestion"}]}, {"id": "marketing-concept-083", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation psychographique ?", "answer": "Elle regroupe les consommateurs selon leur personnalité, leur style de vie, leurs valeurs et leurs motivations.", "sources": [{"documentId": "mf", "page": 5, "excerpt": "Psychographique : caractéristiques psychologiques, aspects intangibles. Reconnaît la diversité des\nstyles de vie au-delà de l'âge ou du revenu ; caractéristiques générales et stables, mais plus\nsubjectives, plus difficiles à mesurer que les critères socio-démographiques.\n•\nAvantages recherchés : regrouper les consommateurs selon la similarité de leurs attentes et\npréférences vis-à-vis d'un produit. Bénéfices fonctionnels, économiques, émotionnels.\n•\nComportemental : basé sur les actes observables ; développé grâce au data mining (analyse de\nbases de données). Exemple : petits écoliers, 2 modes de consommation (à la maison, dans la cour de\nrécré).\n•\nChoix des critères : les responsables marketing utilisent rarement 1 ou 2 critères : segmentation\nmulticritères, qui donne des segments mieux définis et plus homogènes.\n2. Le ciblage", "highlight": "Psychographique :"}]}, {"id": "marketing-concept-084", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation comportementale ?", "answer": "Elle regroupe les consommateurs à partir de comportements observables : fréquence, quantité, occasion ou mode de consommation.", "sources": [{"documentId": "mf", "page": 5, "excerpt": "Comportemental : basé sur les actes observables ; développé grâce au data mining (analyse de\nbases de données). Exemple : petits écoliers, 2 modes de consommation (à la maison, dans la cour de\nrécré).\n•\nChoix des critères : les responsables marketing utilisent rarement 1 ou 2 critères : segmentation\nmulticritères, qui donne des segments mieux définis et plus homogènes.\n2. Le ciblage\nCibler : évaluer les segments du marché et choisir ceux sur lesquels l'entreprise concentrera ses efforts.\n•\nIdéalement une offre = un acheteur, mais le ciblage individuel est souvent impraticable. Défi : trouver\nle bon équilibre entre marketing de masse et marketing one-to-one.\n•\nMarketing de masse (stratégie indifférenciée) : ignore les différences entre individus, une offre\nunique pour tout le marché ; très présent dans la grande distribution.\n•", "highlight": "Comportemental :"}]}, {"id": "marketing-concept-085", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation par avantages recherchés ?", "answer": "Elle regroupe les consommateurs selon les bénéfices qu’ils attendent du produit.", "sources": [{"documentId": "mf", "page": 5, "excerpt": "Avantages recherchés : regrouper les consommateurs selon la similarité de leurs attentes et\npréférences vis-à-vis d'un produit. Bénéfices fonctionnels, économiques, émotionnels.\n•\nComportemental : basé sur les actes observables ; développé grâce au data mining (analyse de\nbases de données). Exemple : petits écoliers, 2 modes de consommation (à la maison, dans la cour de\nrécré).\n•\nChoix des critères : les responsables marketing utilisent rarement 1 ou 2 critères : segmentation\nmulticritères, qui donne des segments mieux définis et plus homogènes.\n2. Le ciblage\nCibler : évaluer les segments du marché et choisir ceux sur lesquels l'entreprise concentrera ses efforts.\n•\nIdéalement une offre = un acheteur, mais le ciblage individuel est souvent impraticable. Défi : trouver\nle bon équilibre entre marketing de masse et marketing one-to-one.\n•", "highlight": "Avantages recherchés :"}]}, {"id": "marketing-concept-086", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation multicritère ?", "answer": "Elle combine plusieurs critères pour former des segments plus précis et plus homogènes, mais généralement plus petits.", "sources": [{"documentId": "mf", "page": 5, "excerpt": "Choix des critères : les responsables marketing utilisent rarement 1 ou 2 critères : segmentation\nmulticritères, qui donne des segments mieux définis et plus homogènes.\n2. Le ciblage\nCibler : évaluer les segments du marché et choisir ceux sur lesquels l'entreprise concentrera ses efforts.\n•\nIdéalement une offre = un acheteur, mais le ciblage individuel est souvent impraticable. Défi : trouver\nle bon équilibre entre marketing de masse et marketing one-to-one.\n•\nMarketing de masse (stratégie indifférenciée) : ignore les différences entre individus, une offre\nunique pour tout le marché ; très présent dans la grande distribution.\n•\nMarketing différencié (multi-segmenté) : plusieurs segments, avec une offre et un marketing-mix\nadaptés à chacun.\n•", "highlight": "Choix des critères :"}]}, {"id": "marketing-concept-087", "chapter": "Segmentation", "question": "Quelles sont les qualités d’un segment utile ?", "answer": "Il doit être substantiel, homogène, différenciable et accessible.", "sources": [{"documentId": "mf", "page": 7, "excerpt": "1.5 Les conditions d'une bonne segmentation\nCondition\nSignification\nDifférenciables\nDistincts et exclusifs, réagissent différemment aux actions marketing\nMesurables\nOn peut quantifier le nombre d'individus et obtenir des données quantitatives et\nqualitatives\nAccessibles\nOn peut les toucher par des moyens spécifiques (point de vente, média)\nSubstantiels\nTaille suffisante pour des investissements rentables. Trop de petits segments =\nsur-segmentation ; seulement de très gros segments = sous-segmentation\nPertinents\nPossibilité d'élaborer des stratégies efficaces, l'entreprise doit avoir une stratégie\ngagnante pour le segment\nActualisables\nDonnées mises à jour, car une segmentation peut vieillir et devenir obsolète\n1.6 Les techniques de segmentation\nMéthode\nPrincipe\nPrécisions\nDescendante ou a\npriori", "highlight": "1.5 Les conditions d'une bonne segmentation"}]}, {"id": "marketing-concept-088", "chapter": "Segmentation", "question": "Quelle différence y a-t-il entre segmentation de l’offre et de la demande ?", "answer": "La segmentation de l’offre regroupe les produits et services. La segmentation de la demande regroupe les consommateurs ou les entreprises clientes.", "sources": [{"documentId": "mf", "page": 6, "excerpt": "1.2 Segmentation de la demande et de l'offre\n•\nDemande : partitionner les consommateurs (B2C) ou les entreprises clientes (B2B) selon des critères\nqui forment des groupes homogènes (segments).\n•\nOffre : regrouper les produits et services selon leurs points communs. Idéalement, un segment de\nconsommateurs correspond à un segment de produits, mais ce n'est pas toujours le cas.\n•\nLa segmentation consommateur guide la réflexion marketing ; la segmentation produit est\nun outil d'analyse.\n•\nLes entreprises utilisent plusieurs types de segmentation en même temps : il n'existe pas de\nsegmentation unique et pertinente.", "highlight": "1.2 Segmentation de la demande et de l'offre"}]}, {"id": "marketing-concept-089", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation descendante ?", "answer": "Elle découpe successivement la population selon des critères choisis à l’avance. On l’appelle aussi segmentation a priori.", "sources": [{"documentId": "mf", "page": 7, "excerpt": "Descendante ou a\npriori\nOn part de toute la population et on fait des\npartitions successives selon des critères\ndéfinis à l'avance (on peut réaliser un arbre\nde segmentation)\nPour un nombre restreint de critères, des\nmarchés mûrs et des problématiques", "highlight": "Descendante ou a"}]}, {"id": "marketing-concept-090", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation ascendante ?", "answer": "Elle regroupe les individus selon leurs ressemblances à partir de nombreuses données. On l’appelle aussi segmentation typologique.", "sources": [{"documentId": "mf", "page": 8, "excerpt": "Ascendante ou\ntypologique\nOn cherche les ressemblances entre\nindividus pour les agréger ; très grand\nnombre de données, sans savoir à l'avance\nlesquelles serviront\nAnalyses factorielles (composantes principales,\ncorrespondances) et typologiques (nuées\ndynamiques, centres mobiles, classification\nhiérarchique). Traitement statistique :\nindividus semblables regroupés en types,\ntypes les plus éloignés possible. Limite :\nfrontières floues entre les types ; chaque type\nse décrit par son centre de gravité\n(moyenne des variables)\n2. Le ciblage\nLa segmentation forme des groupes aux attentes et comportements homogènes. Il faut ensuite analyser\npour choisir un ou plusieurs segments prioritaires. Le ciblage est une décision stratégique : elle\ndétermine d'autres choix stratégiques (positionnement) et opérationnels (marketing-mix).", "highlight": "Ascendante ou"}]}, {"id": "marketing-concept-091", "chapter": "Segmentation", "question": "Quels critères permettent de segmenter un marché B2B ?", "answer": "Le secteur d’activité, la taille, les performances économiques, la localisation, le processus de décision, les critères de choix des fournisseurs et la fidélité.", "sources": [{"documentId": "mf", "page": 7, "excerpt": "1.4 Segmenter la demande en B2B\nMême logique que pour les particuliers, mais les décideurs sont rarement les destinataires et\nutilisateurs du produit acheté. Critères utiles :\n•\nSecteur d'activité : périmètre d'activité des entreprises acheteuses.\n•\nTaille de l'entreprise : impact sur le potentiel et le renouvellement des commandes (petits, moyens,\ngros clients).\n•\nPerformances économiques : distinguer entreprises saines et fragiles.\n•\nLocalisation : délais de transport ; pour les services, rapidité d'intervention.\n•\nProcessus de décision : qui décide, décisions centralisées ou décentralisées, procédure simple ou\ncomplexe.\n•\nCritères de choix des fournisseurs : fonctionnels (configuration, qualité, délais) ou financiers\n(budget, optimisation des coûts).\n•\nNiveau de fidélité : clients fidélisés, perdus, nouveaux, prospects.", "highlight": "1.4 Segmenter la demande en B2B"}]}, {"id": "marketing-concept-092", "chapter": "Ciblage", "question": "Quelle est la définition du ciblage ?", "answer": "Le ciblage consiste à évaluer les segments puis à choisir celui ou ceux sur lesquels l’entreprise concentrera ses efforts.", "sources": [{"documentId": "mf", "page": 5, "excerpt": "Cibler : évaluer les segments du marché et choisir ceux sur lesquels l'entreprise concentrera ses efforts.\n•\nIdéalement une offre = un acheteur, mais le ciblage individuel est souvent impraticable. Défi : trouver\nle bon équilibre entre marketing de masse et marketing one-to-one.\n•\nMarketing de masse (stratégie indifférenciée) : ignore les différences entre individus, une offre\nunique pour tout le marché ; très présent dans la grande distribution.\n•\nMarketing différencié (multi-segmenté) : plusieurs segments, avec une offre et un marketing-mix\nadaptés à chacun.\n•\nFacteurs du choix : ressources de l'entreprise · potentiel de différenciation des produits · phase du\ncycle de vie du marché · hétérogénéité du marché · stratégies des concurrents.\n3. Le positionnement", "highlight": "Cibler :"}]}, {"id": "marketing-concept-093", "chapter": "Ciblage", "question": "Sur quels critères choisit-on une cible ?", "answer": "On évalue l’attractivité du segment et sa compatibilité avec les objectifs, ressources et compétences de l’entreprise.", "sources": [{"documentId": "mf", "page": 8, "excerpt": "2.1 L'évaluation des segments\nAttractivité : taille (valeur et volume), dynamisme (croissance), intensité concurrentielle, accessibilité\n(obstacles à l'entrée), rentabilité, perspectives de développement. Il n'y a pas de seuil établi : un très\npetit segment peut être très rentable, un grand segment peut être difficile d'accès à cause de la\nconcurrence.\nAdéquation aux moyens de l'entreprise : moyens financiers (budget) · technologiques\n(savoir-faire) · humains et organisationnels (structure commerciale) · informationnels (informations\nnécessaires).\nAdéquation à la stratégie de l'entreprise : le ciblage doit être compatible avec la stratégie générale.\n•\nMission : donne les marchés, produits, zones géographiques et clientèle visée.\n•\nBusiness model : façon de créer de la valeur et de la répartir entre l'entreprise et ses clients (ex.", "highlight": "2.1 L'évaluation des segments"}]}, {"id": "marketing-concept-094", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage indifférencié ?", "answer": "Il consiste à proposer une offre commune à l’ensemble du marché, en privilégiant les besoins partagés.", "sources": [{"documentId": "mf", "page": 5, "excerpt": "Marketing de masse (stratégie indifférenciée) : ignore les différences entre individus, une offre\nunique pour tout le marché ; très présent dans la grande distribution.\n•\nMarketing différencié (multi-segmenté) : plusieurs segments, avec une offre et un marketing-mix\nadaptés à chacun.\n•\nFacteurs du choix : ressources de l'entreprise · potentiel de différenciation des produits · phase du\ncycle de vie du marché · hétérogénéité du marché · stratégies des concurrents.\n3. Le positionnement\nDéfinition : conception d'un produit et de son image pour lui donner une place déterminée dans", "highlight": "Marketing de masse"}]}, {"id": "marketing-concept-095", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage différencié ?", "answer": "Il consiste à servir plusieurs segments avec une offre et un marketing mix adaptés à chacun.", "sources": [{"documentId": "mf", "page": 5, "excerpt": "Marketing différencié (multi-segmenté) : plusieurs segments, avec une offre et un marketing-mix\nadaptés à chacun.\n•\nFacteurs du choix : ressources de l'entreprise · potentiel de différenciation des produits · phase du\ncycle de vie du marché · hétérogénéité du marché · stratégies des concurrents.\n3. Le positionnement\nDéfinition : conception d'un produit et de son image pour lui donner une place déterminée dans", "highlight": "Marketing différencié"}]}, {"id": "marketing-concept-096", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage concentré ?", "answer": "Il consiste à concentrer les efforts sur un segment particulier. Une niche est un segment particulièrement étroit et spécifique.", "sources": [{"documentId": "mf", "page": 9, "excerpt": "Concentré\nUn seul segment, offre et plan marketing\nadaptés à ce segment\nMicro-marketing ou\none-to-one\nIndividualiser et personnaliser l'offre,\nparfois jusqu'au sur-mesure\nProblème : la rentabilité\n3. Le positionnement\n3.1 Dimensions\n•\nLe positionnement décrit ce qu'est le produit, à quoi il sert et en quoi il se distingue. Il porte sur\ndes bénéfices fonctionnels, des caractéristiques physiques et des éléments symboliques. Un\npositionnement fort fait les grandes marques.\n•\nC'est le choix de traits saillants et distinctifs qui permettent de situer l'offre parmi les produits\ncomparables : une représentation simplifiée, réductrice, comparative et distinctive.\n•\nIl est la clé de voûte et le facteur de cohérence du marketing-mix.\n•\n4 grands thèmes : performances du produit · imaginaire de marque · publics cibles · mode\nd'utilisation.\n•", "highlight": "Concentré"}]}, {"id": "marketing-concept-097", "chapter": "Ciblage", "question": "Qu’est-ce que le marketing individualisé ?", "answer": "C’est l’adaptation de tout ou partie de l’offre à chaque individu. On l’appelle aussi marketing one to one.", "sources": [{"documentId": "mf", "page": 9, "excerpt": "Micro-marketing ou\none-to-one\nIndividualiser et personnaliser l'offre,\nparfois jusqu'au sur-mesure\nProblème : la rentabilité\n3. Le positionnement\n3.1 Dimensions\n•\nLe positionnement décrit ce qu'est le produit, à quoi il sert et en quoi il se distingue. Il porte sur\ndes bénéfices fonctionnels, des caractéristiques physiques et des éléments symboliques. Un\npositionnement fort fait les grandes marques.\n•\nC'est le choix de traits saillants et distinctifs qui permettent de situer l'offre parmi les produits\ncomparables : une représentation simplifiée, réductrice, comparative et distinctive.\n•\nIl est la clé de voûte et le facteur de cohérence du marketing-mix.\n•\n4 grands thèmes : performances du produit · imaginaire de marque · publics cibles · mode\nd'utilisation.\n•\nQuel que soit l'axe, il répond à un avantage recherché, explicite ou implicite.", "highlight": "Micro-marketing ou"}]}, {"id": "marketing-concept-098", "chapter": "Ciblage", "question": "Qu’est-ce qu’un persona ?", "answer": "C’est un personnage fictif représentant un groupe de clients, construit à partir de données réelles sur leurs profils, comportements et motivations."}, {"id": "marketing-concept-099", "chapter": "Positionnement", "question": "Quelle est la définition du positionnement ?", "answer": "Le positionnement vise à donner à l’offre une place claire et distinctive dans l’esprit des clients ciblés, par rapport aux concurrents.", "sources": [{"documentId": "mf", "page": 9, "excerpt": "3.1 Dimensions\n•\nLe positionnement décrit ce qu'est le produit, à quoi il sert et en quoi il se distingue. Il porte sur\ndes bénéfices fonctionnels, des caractéristiques physiques et des éléments symboliques. Un\npositionnement fort fait les grandes marques.\n•\nC'est le choix de traits saillants et distinctifs qui permettent de situer l'offre parmi les produits\ncomparables : une représentation simplifiée, réductrice, comparative et distinctive.\n•\nIl est la clé de voûte et le facteur de cohérence du marketing-mix.\n•\n4 grands thèmes : performances du produit · imaginaire de marque · publics cibles · mode\nd'utilisation.\n•\nQuel que soit l'axe, il répond à un avantage recherché, explicite ou implicite.\nIdentification : le consommateur doit identifier immédiatement le produit, rattaché à une catégorie", "highlight": "3.1 Dimensions"}]}, {"id": "marketing-concept-100", "chapter": "Positionnement", "question": "Quelles sont les deux composantes du positionnement ?", "answer": "L’identification, qui rattache l’offre à une catégorie, et la différenciation, qui la distingue des offres concurrentes.", "sources": [{"documentId": "mf", "page": 6, "excerpt": "Deux éléments constitutifs :\n1. Identification : rattacher le produit à une catégorie, à un univers de consommation (« de quel genre\nde produit s'agit-il ? »).\n2. Différenciation : distinguer le produit dans sa catégorie (point de différence). Attributs possibles :\ngoût, couleur, odeur, texture, fiabilité, prestige, naturalité, caractère équitable, circuit de distribution,\ncomportement des vendeurs, service commercial.\nÉnoncé de positionnement : « Pour les gens qui… la marque X est… qui apporte… »\nMéthode SCP en détail (cours Louvrier)\nLa méthode SCP est une démarche en trois temps (segmentation, ciblage, positionnement, ou\nsegmentation, targeting, positioning). Elle établit des orientations claires, qui doivent se refléter dans\ntoutes les actions du plan marketing opérationnel.\nÉtape\nRôle\n1. Segmentation", "highlight": "Deux éléments constitutifs"}]}, {"id": "marketing-concept-101", "chapter": "Positionnement", "question": "Qu’est-ce que la différenciation ?", "answer": "C’est le choix d’attributs ou de bénéfices valorisés par la cible qui distinguent l’offre de celle des concurrents.", "sources": [{"documentId": "mf", "page": 6, "excerpt": "2. Différenciation : distinguer le produit dans sa catégorie (point de différence). Attributs possibles :\ngoût, couleur, odeur, texture, fiabilité, prestige, naturalité, caractère équitable, circuit de distribution,\ncomportement des vendeurs, service commercial.\nÉnoncé de positionnement : « Pour les gens qui… la marque X est… qui apporte… »\nMéthode SCP en détail (cours Louvrier)\nLa méthode SCP est une démarche en trois temps (segmentation, ciblage, positionnement, ou\nsegmentation, targeting, positioning). Elle établit des orientations claires, qui doivent se refléter dans\ntoutes les actions du plan marketing opérationnel.\nÉtape\nRôle\n1. Segmentation\nRéduire la complexité et la diversité des profils de consommateurs en identifiant des\nsous-groupes aux caractéristiques communes\n2. Ciblage", "highlight": "2. Différenciation"}]}, {"id": "marketing-concept-102", "chapter": "Positionnement", "question": "Comment formule-t-on un énoncé de positionnement ?", "answer": "« Pour [cible], la marque X est [catégorie] qui apporte [bénéfice distinctif]. »", "sources": [{"documentId": "mf", "page": 6, "excerpt": "Énoncé de positionnement : « Pour les gens qui… la marque X est… qui apporte… »\nMéthode SCP en détail (cours Louvrier)\nLa méthode SCP est une démarche en trois temps (segmentation, ciblage, positionnement, ou\nsegmentation, targeting, positioning). Elle établit des orientations claires, qui doivent se refléter dans\ntoutes les actions du plan marketing opérationnel.\nÉtape\nRôle\n1. Segmentation\nRéduire la complexité et la diversité des profils de consommateurs en identifiant des\nsous-groupes aux caractéristiques communes\n2. Ciblage\nÉvaluer chaque segment et décider de se spécialiser sur un ou plusieurs\n3. Positionnement\nDéfinir l'offre par rapport à la cible et à la concurrence pour qu'elle soit la meilleure\npossible\n1. La segmentation\n1.1 Objectifs et intérêts\n•", "highlight": "Énoncé de positionnement"}]}, {"id": "marketing-concept-103", "chapter": "Positionnement", "question": "Quels sont les critères d’un bon positionnement ?", "answer": "Il doit être attractif, différenciant, crédible, simple, profitable et pérenne.", "sources": [{"documentId": "mf", "page": 9, "excerpt": "3.2 Évaluation du positionnement\nIl faut savoir l'évaluer pour comprendre la dynamique d'une marque et déceler des zones d'optimisation.\nCritère\nSignification\nAttractivité\nAttirant pour la cible, en phase avec ses attentes (exprimées ou latentes)\nDifférenciation\nDifférent de l'offre existante, ce qui justifie le produit\nCrédibilité\nLes consommateurs croient que le produit tiendra ses promesses\nSimple\nPeu de caractéristiques ; doit tenir en une phrase\nProfitable\nCible au potentiel économique suffisant (un segment peut être rentable pour une PME et\npas pour une multinationale)\nPérenne\nInvestissement à long terme, mais il faut rester pertinent face à des marchés qui\névoluent\n3.3 Stratégies de positionnement\nGestion du positionnement\n•\nIdentifier les avantages concurrentiels pertinents pour la cible.\n•", "highlight": "3.2 Évaluation du positionnement"}]}, {"id": "marketing-concept-104", "chapter": "Positionnement", "question": "Que signifie USP ?", "answer": "Unique Selling Proposition : une proposition de vente unique qui met en avant un bénéfice principal et distinctif.", "sources": [{"documentId": "mf", "page": 9, "excerpt": "Mettre en avant un seul bénéfice = USP (Unique Selling Proposition) : positionnement plus clair dans\nl'esprit des consommateurs. Ou plusieurs bénéfices, choisis avec des critères : importance pour la\ncible, caractère distinctif, supériorité sur la concurrence, facilité à communiquer, caractère défendable\net justifiable, rentabilité.\n•\nLe positionnement est intégré aux briefs de chaque action marketing, et sa perception par les", "highlight": "Mettre en avant un seul bénéfice"}]}], "documents": ["mf"]}, {"id": "communication", "title": "Communication commerciale", "description": "Définitions et notions essentielles de communication.", "symbol": "C", "storageKey": "declic-communication-concepts-v3", "cards": [{"id": "communication-concept-001", "chapter": "1 · Les fondamentaux", "question": "Quelle est la définition de la communication d’une entreprise ?", "answer": "C’est l’ensemble des informations, messages et signaux qu’une entreprise émet, volontairement ou non, vers tous ses publics.", "sources": [{"documentId": "com", "page": 1, "excerpt": "Communication : ensemble des informations, messages et signaux de toute nature \nqu'une entreprise émet, volontairement ou non, vers tous ses publics.\n\nCommunication commerciale : ensemble des actions mises en œuvre par une \nentreprise pour influencer positivement les attitudes et comportements de ses \npublics, dans une perspective de performance économique.\n4 fonctions : INFORMER · SÉDUIRE · CONVAINCRE · FIDÉLISER\nFonction\nObjectif\nInformer", "highlight": "ensemble des informations"}]}, {"id": "communication-concept-002", "chapter": "1 · Les fondamentaux", "question": "Quelle est la définition de la communication commerciale ?", "answer": "C’est l’ensemble des actions visant à influencer positivement les attitudes et comportements des publics dans une perspective de performance économique.", "sources": [{"documentId": "com", "page": 1, "excerpt": "entreprise pour influencer positivement les attitudes et comportements de ses \npublics, dans une perspective de performance économique.\n4 fonctions : INFORMER · SÉDUIRE · CONVAINCRE · FIDÉLISER\nFonction\nObjectif\nInformer\nFaire connaître un produit ou une marque\nSéduire\nAttirer l'attention, provoquer une émotion\nConvaincre Déclencher l'achat\nFidéliser\nRenforcer la relation à long terme\n2 objectifs majeurs\n", "highlight": "influencer positivement"}]}, {"id": "communication-concept-003", "chapter": "1 · Les fondamentaux", "question": "Quelles sont les quatre fonctions de la communication commerciale ?", "answer": "Informer, séduire, convaincre et fidéliser.", "sources": [{"documentId": "com", "page": 1, "excerpt": "4 fonctions : INFORMER · SÉDUIRE · CONVAINCRE · FIDÉLISER\nFonction\nObjectif\nInformer\nFaire connaître un produit ou une marque\nSéduire\nAttirer l'attention, provoquer une émotion\nConvaincre Déclencher l'achat\nFidéliser\nRenforcer la relation à long terme\n2 objectifs majeurs\n\nÉconomiques : augmenter les ventes, conquérir des parts de marché, fidéliser la \nclientèle.\n\nSymboliques : créer de la valeur immatérielle (image, notoriété, crédibilité).", "highlight": "INFORMER"}]}, {"id": "communication-concept-004", "chapter": "1 · Les fondamentaux", "question": "Quelle différence y a-t-il entre objectifs économiques et symboliques de communication ?", "answer": "Les objectifs économiques concernent notamment les ventes, les parts de marché et la fidélisation. Les objectifs symboliques concernent l’image, la notoriété et la crédibilité.", "sources": [{"documentId": "com", "page": 1, "excerpt": "Symboliques : créer de la valeur immatérielle (image, notoriété, crédibilité).\nÉvolution\n\nAux acteurs classiques s'ajoutent les influenceurs et créateurs de contenu.\n\nEnjeux : relation durable, montrer ses valeurs, gérer sa réputation.\nTypes de communication\nObjet de la communication\nType\nProduits / services\nCommunication de produit\nLa marque\nCommunication de marque\nL'entreprise\nCommunication institutionnelle", "highlight": "Symboliques"}]}, {"id": "communication-concept-005", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la communication institutionnelle ?", "answer": "C’est la communication qui porte sur l’entreprise dans son ensemble.", "sources": [{"documentId": "com", "page": 1, "excerpt": "Communication institutionnelle\nSecteur ou entreprise en crise Communication de crise\nLe personnel\nCommunication interne\nActionnaires / investisseurs\nCommunication externe (financière)\nLes candidats", "highlight": "institutionnelle"}]}, {"id": "communication-concept-006", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la communication de produit ?", "answer": "Elle fait connaître le produit et ses caractéristiques, en restant cohérente avec l’image de marque.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Com. de produit : faire connaître le produit et ses caractéristiques, en restant \ncohérente avec l'image de marque.\n\nCom. de marque : utile sur les marchés très concurrentiels ou les produits à forte \nvaleur imaginaire ; crée un territoire de marque distinctif qui fidélise.\nPlace dans le mix marketing\n4P = Produit · Prix · Place · Promotion (= communication).\n\nLa communication est la partie visible du marketing et assure la cohérence du mix.\n", "highlight": "Com. de produit"}]}, {"id": "communication-concept-007", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la communication de marque ?", "answer": "Elle construit un territoire de marque distinctif et favorise la différenciation et la fidélisation.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Com. de marque : utile sur les marchés très concurrentiels ou les produits à forte \nvaleur imaginaire ; crée un territoire de marque distinctif qui fidélise.\nPlace dans le mix marketing\n4P = Produit · Prix · Place · Promotion (= communication).\n\nLa communication est la partie visible du marketing et assure la cohérence du mix.\n\nUne stratégie = organiser des choix cohérents.\n", "highlight": "Com. de marque"}]}, {"id": "communication-concept-008", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce qu’un annonceur ?", "answer": "C’est l’entreprise qui commande une campagne de communication.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Annonceurs\nEntreprises qui commandent la campagne (Nike, Decathlon, Orange)\nAgences\nConçoivent les campagnes (Publicis, BETC)\nMédias et supports Diffusent le message (presse, télé, affichage, réseaux sociaux, \ninfluenceurs)\nRégies publicitaires Vendent et achètent des espaces pub selon prix, horaire, emplacement, \njour\nPublics\nConsommateurs, prescripteurs, leaders d'opinion, associations, \ninstitutions", "highlight": "Annonceurs"}]}, {"id": "communication-concept-009", "chapter": "1 · Les fondamentaux", "question": "Quel est le rôle d’une agence de communication ?", "answer": "Elle conçoit les campagnes de communication.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Agences\nConçoivent les campagnes (Publicis, BETC)\nMédias et supports Diffusent le message (presse, télé, affichage, réseaux sociaux, \ninfluenceurs)\nRégies publicitaires Vendent et achètent des espaces pub selon prix, horaire, emplacement, \njour\nPublics\nConsommateurs, prescripteurs, leaders d'opinion, associations, \ninstitutions\nMétiers d'une agence : département stratégie (planneur stratégique) · service médias ·", "highlight": "Agences"}]}, {"id": "communication-concept-010", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce qu’une régie publicitaire ?", "answer": "C’est un intermédiaire qui commercialise les espaces publicitaires des médias auprès des annonceurs et des agences.", "sources": [{"documentId": "com", "page": 5, "excerpt": "Régies publicitaires : elles commercialisent, auprès des annonceurs et des agences, \nles espaces publicitaires des médias dont elles ont la charge. Elles sont intermédiaires \nentre l'annonceur et le diffuseur.\n\nAgences, détail des métiers : les créatifs incluent le directeur de la création, les \ndirecteurs artistiques, les concepteurs-rédacteurs, graphistes, motion designers,", "highlight": "Régie"}]}, {"id": "communication-concept-011", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la saturation publicitaire ?", "answer": "C’est la surabondance de messages publicitaires reçus par le public. Elle peut entraîner une fatigue et une moindre attention aux publicités.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Saturation publicitaire : trop de messages.\n\nFragmentation des audiences : chacun consomme des médias différents.\n\nDigital : réseaux sociaux, data, ciblage personnalisé.\n\nAttentes sociétales : transparence, durabilité, inclusion.\n\nInstantanéité : la marque doit être active ; un bad buzz est un danger.", "highlight": "Saturation"}]}, {"id": "communication-concept-012", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la fragmentation des audiences ?", "answer": "C’est la dispersion des publics entre de nombreux médias et supports.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Fragmentation des audiences : chacun consomme des médias différents.\n\nDigital : réseaux sociaux, data, ciblage personnalisé.\n\nAttentes sociétales : transparence, durabilité, inclusion.\n\nInstantanéité : la marque doit être active ; un bad buzz est un danger.", "highlight": "Fragmentation"}]}, {"id": "communication-concept-013", "chapter": "2 · La stratégie", "question": "Quelle est la définition d’une stratégie de communication ?", "answer": "C’est l’ensemble des choix et orientations qui guident les actions de communication pour atteindre des objectifs précis auprès de cibles identifiées.", "sources": [{"documentId": "com", "page": 3, "excerpt": "Ensemble des choix et orientations qui guident les actions de communication d'une \norganisation pour atteindre des objectifs précis auprès de cibles identifiées.\nElle répond à : quoi dire, comment, à qui, quand, pourquoi ? (le bon message, à la bonne \ncible, par le bon canal).\nElle doit être : alignée avec la stratégie globale · cohérente avec l'image de marque · \nmesurable (indicateurs de performance).\nLes 3 étapes\nÉtape 1 – Diagnostic\n", "highlight": "choix et orientations"}]}, {"id": "communication-concept-014", "chapter": "2 · La stratégie", "question": "Quelles sont les quatre étapes d’une stratégie de communication ?", "answer": "Diagnostic, objectifs de communication, cibles, puis positionnement et message ou stratégie créative.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Les 4 étapes\n1. Diagnostic · 2. Objectif de communication · 3. Cibles · 4. Positionnement et message \n(stratégie créative)\nDiagnostic, compléments : outil = matrice SWOT (forces, faiblesses, opportunités, \nmenaces). L'ensemble de ces données approfondies = audit de la communication.\nHiérarchie des effets appliquée aux objectifs :\nStade\nIdée\nContenu\nCognitif Faire savoir Notoriété, info produit, stimuler l'attention", "highlight": "Les 4 étapes"}]}, {"id": "communication-concept-015", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’un audit de communication ?", "answer": "C’est l’analyse approfondie de la situation de communication de l’organisation. Le diagnostic est notamment synthétisé dans une matrice SWOT.", "sources": [{"documentId": "com", "page": 6, "excerpt": "menaces). L'ensemble de ces données approfondies = audit de la communication.\nHiérarchie des effets appliquée aux objectifs :\nStade\nIdée\nContenu\nCognitif Faire savoir Notoriété, info produit, stimuler l'attention\nAffectif Faire aimer Attrait, effet sur l'image, préférence, éveiller l'intérêt\nConatif Faire agir\nAchat, conviction, créer du trafic, inciter à l'essai\nCibles, compléments\n", "highlight": "audit"}]}, {"id": "communication-concept-016", "chapter": "2 · La stratégie", "question": "Quels sont les trois objectifs de communication ?", "answer": "Cognitif : faire savoir ou connaître. Affectif : faire aimer. Conatif : faire agir.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Cognitif Faire savoir Notoriété, info produit, stimuler l'attention\nAffectif Faire aimer Attrait, effet sur l'image, préférence, éveiller l'intérêt\nConatif Faire agir\nAchat, conviction, créer du trafic, inciter à l'essai\nCibles, compléments\n\nCible marketing : clients actuels et prospects que l'on peut toucher. Elle prend en \ncompte un marché identifié, la concurrence et les clients potentiels, pour répondre aux", "highlight": "Faire savoir"}]}, {"id": "communication-concept-017", "chapter": "2 · La stratégie", "question": "Que signifie SMART pour un objectif ?", "answer": "Spécifique, mesurable, atteignable, réaliste et temporel.", "sources": [{"documentId": "com", "page": 3, "excerpt": "Méthode SMART\nLettre\nCritère\nSens\nS\nSpécifique Précis et clair\nM\nMesurable Peut être mesuré\nA\nAtteignable Réalisable avec les compétences et ressources disponibles\nR\nRéaliste\nEn adéquation avec les contraintes et capacités actuelles\nT\nTemporel\nDate d'échéance définie\nÉtape 3 – Cibles\n\nStratégie marketing : segmentation → ciblage → positionnement.\n\nCible marketing = à qui l'entreprise vend. Cible de communication = à qui \nelle parle.\n", "highlight": "SMART"}]}, {"id": "communication-concept-018", "chapter": "2 · La stratégie", "question": "Quelle différence y a-t-il entre cible marketing et cible de communication ?", "answer": "La cible marketing désigne les personnes à qui l’entreprise vend. La cible de communication désigne les personnes à qui elle s’adresse.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Cible marketing : clients actuels et prospects que l'on peut toucher. Elle prend en \ncompte un marché identifié, la concurrence et les clients potentiels, pour répondre aux \nbesoins du mix marketing (prix, distribution…).\n\nCible principale : personnes directement concernées par le produit ou service ; \ncaractérisée par âge, sexe, lieu géographique, centres d'intérêt, CSP.\n", "highlight": "Cible marketing"}]}, {"id": "communication-concept-019", "chapter": "2 · La stratégie", "question": "Qu’est-ce que la cible principale ?", "answer": "Ce sont les personnes directement concernées par le produit ou le service.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Cible principale : personnes directement concernées par le produit ou service ; \ncaractérisée par âge, sexe, lieu géographique, centres d'intérêt, CSP.\n\nHiérarchisation des cibles : prise en compte du circuit de distribution et \ndu processus de décision d'achat(consommateur, acheteur, prescripteurs).\nConnaître et comprendre ses cibles : l'insight\n\nÀ comprendre : motivations profondes (hédonistes, oblatives, auto-", "highlight": "Cible principale"}]}, {"id": "communication-concept-020", "chapter": "2 · La stratégie", "question": "Qu’est-ce que le cœur de cible ?", "answer": "C’est le sous-ensemble prioritaire de la cible principale.", "sources": [{"documentId": "com", "page": 4, "excerpt": "Cœur de cible : sous-ensemble de la cible principale, touché en premier, avec des \ncritères supplémentaires pour resserrer.\n\nCibles secondaires : ne concernent pas directement la marque mais la \nrecommandent : prescripteurs, distributeurs (force de vente), journalistes.\nMémo express\n\n4 fonctions : informer, séduire, convaincre, fidéliser.\n\n4P : produit, prix, place, promotion.\n\n3 objectifs : notoriété, image, action.\n", "highlight": "Cœur de cible"}]}, {"id": "communication-concept-021", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’une cible secondaire ?", "answer": "C’est un public qui peut recommander, relayer ou influencer l’achat sans être la cible principale.", "sources": [{"documentId": "com", "page": 4, "excerpt": "Cibles secondaires : ne concernent pas directement la marque mais la \nrecommandent : prescripteurs, distributeurs (force de vente), journalistes.\nMémo express\n\n4 fonctions : informer, séduire, convaincre, fidéliser.\n\n4P : produit, prix, place, promotion.\n\n3 objectifs : notoriété, image, action.\n\nSMART : spécifique, mesurable, atteignable, réaliste, temporel.\n\nCiblage : principale → cœur de cible → secondaires.", "highlight": "Cibles secondaires"}]}, {"id": "communication-concept-022", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’un insight consommateur ?", "answer": "C’est la perception d’un problème ou d’un dilemme non résolu dans une catégorie de produits. Il révèle une motivation, un besoin ou un manque.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Connaître et comprendre ses cibles : l'insight\n\nÀ comprendre : motivations profondes (hédonistes, oblatives, auto-\nexpression), freins (peurs, inhibitions, risques), besoins, attentes, perception.\n\nInsight : perception par le consommateur d'un problème ou dilemme irrésolu sur la \ncatégorie de produits où la marque opère. Notion clé : motivation ou besoin sous-\njacent, signe avant-coureur, constat d'un manque.\n", "highlight": "insight"}]}, {"id": "communication-concept-023", "chapter": "2 · La stratégie", "question": "Quelles sont les trois grandes motivations du consommateur ?", "answer": "Hédonistes : se faire plaisir. Oblatives : faire plaisir aux autres. Auto-expression : exprimer sa personnalité ou l’image de soi.", "sources": [{"documentId": "com", "page": 6, "excerpt": "À comprendre : motivations profondes (hédonistes, oblatives, auto-\nexpression), freins (peurs, inhibitions, risques), besoins, attentes, perception.\n\nInsight : perception par le consommateur d'un problème ou dilemme irrésolu sur la \ncatégorie de produits où la marque opère. Notion clé : motivation ou besoin sous-\njacent, signe avant-coureur, constat d'un manque.\n\nComment l'analyser : observation → motivation → frein → réponse de la marque.\n", "highlight": "hédonistes"}]}, {"id": "communication-concept-024", "chapter": "2 · La stratégie", "question": "Quels sont les principaux freins à l’achat ?", "answer": "Les peurs, les inhibitions et les risques perçus.", "sources": [{"documentId": "com", "page": 6, "excerpt": "expression), freins (peurs, inhibitions, risques), besoins, attentes, perception.\n\nInsight : perception par le consommateur d'un problème ou dilemme irrésolu sur la \ncatégorie de produits où la marque opère. Notion clé : motivation ou besoin sous-\njacent, signe avant-coureur, constat d'un manque.\n\nComment l'analyser : observation → motivation → frein → réponse de la marque.\n", "highlight": "freins"}]}, {"id": "communication-concept-025", "chapter": "2 · La stratégie", "question": "Quelle est la définition du positionnement ?", "answer": "C’est l’ensemble des traits saillants qui permettent au consommateur d’identifier l’offre et de la différencier de ses concurrents.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Positionnement (Ries et Trout) : ensemble des traits saillants qui permettent aux \nconsommateurs d'identifier le produit et de le différencier de l'univers des produits \nconcurrents.\nPourquoi positionner ? Se différencier des concurrents · répondre aux attentes clients · être", "highlight": "Positionnement (Ries"}]}, {"id": "communication-concept-026", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’une copy stratégie ?", "answer": "C’est un brief créatif qui synthétise la réflexion stratégique et fixe ce que le message doit communiquer.", "sources": [{"documentId": "com", "page": 7, "excerpt": "La stratégie créative = copy stratégie (brief créatif)\nElle expose les points clés de la réflexion stratégique et pose les axes de création. C'est le plan \nqui permet à l'annonceur de comprendre le travail de l'agence, une méthode synthétique pour \nexprimer ce que le message doit communiquer.\nÉlément\nDéfinition\nPromesse\nCe que la marque promet d'apporter au consommateur. Elle doit \nêtre unique (USP), simple (adaptée aux connaissances de la", "highlight": "copy stratégie"}]}, {"id": "communication-concept-027", "chapter": "2 · La stratégie", "question": "Quels sont les éléments d’une copy stratégie ?", "answer": "Promesse, bénéfice consommateur, avantage produit, ton, preuves et contraintes.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Bénéfice \nconsommateur\nCe que le consommateur retire de l'utilisation de la marque\nAvantage produit Performance du produit\nTon\nClimat / atmosphère du message : explicatif, démonstratif, informatif, \nhumoristique, imaginaire, symbolique\nPreuves\nJustifier la promesse par des éléments concrets\nContraintes\nLégales, de temps, de budget, respect de la charte graphique", "highlight": "Bénéfice \nconsommateur"}]}, {"id": "communication-concept-028", "chapter": "2 · La stratégie", "question": "Qu’est-ce que la promesse publicitaire ?", "answer": "C’est ce que la marque promet d’apporter au consommateur. Elle doit être unique, simple et ne pas enfermer la création.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Promesse\nCe que la marque promet d'apporter au consommateur. Elle doit \nêtre unique (USP), simple (adaptée aux connaissances de la \ncible), abstraite (pour ne pas contraindre la création)\nBénéfice \nconsommateur\nCe que le consommateur retire de l'utilisation de la marque\nAvantage produit Performance du produit\nTon\nClimat / atmosphère du message : explicatif, démonstratif, informatif, \nhumoristique, imaginaire, symbolique\nPreuves", "highlight": "Promesse"}]}, {"id": "communication-concept-029", "chapter": "2 · La stratégie", "question": "Quelle différence y a-t-il entre bénéfice consommateur et avantage produit ?", "answer": "Le bénéfice est ce que le consommateur retire de l’usage. L’avantage produit est une performance ou caractéristique du produit.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Avantage produit Performance du produit\nTon\nClimat / atmosphère du message : explicatif, démonstratif, informatif, \nhumoristique, imaginaire, symbolique\nPreuves\nJustifier la promesse par des éléments concrets\nContraintes\nLégales, de temps, de budget, respect de la charte graphique\nElle fixe un cadre à partir duquel la création se développe, et doit reposer sur un bénéfice \ntangible, simple, clair et cohérent.", "highlight": "Avantage produit"}]}, {"id": "communication-concept-030", "chapter": "2 · La stratégie", "question": "Qu’est-ce que le ton d’un message publicitaire ?", "answer": "C’est le climat ou l’atmosphère du message : informatif, démonstratif, humoristique, imaginaire ou symbolique, notamment.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Climat / atmosphère du message : explicatif, démonstratif, informatif, \nhumoristique, imaginaire, symbolique\nPreuves\nJustifier la promesse par des éléments concrets\nContraintes\nLégales, de temps, de budget, respect de la charte graphique\nElle fixe un cadre à partir duquel la création se développe, et doit reposer sur un bénéfice \ntangible, simple, clair et cohérent.", "highlight": "Climat"}]}, {"id": "communication-concept-031", "chapter": "2 · La stratégie", "question": "À quoi servent les preuves dans une copy stratégie ?", "answer": "Elles justifient la promesse par des éléments concrets.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Justifier la promesse par des éléments concrets\nContraintes\nLégales, de temps, de budget, respect de la charte graphique\nElle fixe un cadre à partir duquel la création se développe, et doit reposer sur un bénéfice \ntangible, simple, clair et cohérent.\nExemple : agence de voyage low cost. Promesse : les prix les plus bas · Bénéfice : voyager \nplus · Ton : détendu, exotique · Preuve : les prix de l'agence · Contraintes : charte graphique,", "highlight": "Justifier la promesse"}]}, {"id": "communication-concept-032", "chapter": "2 · La stratégie", "question": "Quelles contraintes encadrent une copy stratégie ?", "answer": "Les contraintes peuvent être légales, temporelles, budgétaires ou liées à la charte graphique.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Contraintes\nLégales, de temps, de budget, respect de la charte graphique\nElle fixe un cadre à partir duquel la création se développe, et doit reposer sur un bénéfice \ntangible, simple, clair et cohérent.\nExemple : agence de voyage low cost. Promesse : les prix les plus bas · Bénéfice : voyager \nplus · Ton : détendu, exotique · Preuve : les prix de l'agence · Contraintes : charte graphique, \nlogo du partenaire.", "highlight": "Contraintes"}]}, {"id": "communication-concept-033", "chapter": "3 · Les théories", "question": "Quels sont les éléments du modèle de Lasswell ?", "answer": "L’émetteur, le message, la cible, le canal et l’effet. Le modèle se résume par « Qui dit quoi, à qui, par quel canal, avec quel effet ? ».", "sources": [{"documentId": "com", "page": 7, "excerpt": "« Qui dit quoi, à qui, par quel canal, avec quel effet ? »\nQuestion\nÉlément", "highlight": "Qui dit quoi"}]}, {"id": "communication-concept-034", "chapter": "3 · Les théories", "question": "Quelle est la principale limite du modèle de Shannon et Weaver présenté dans le cours ?", "answer": "C’est un modèle linéaire ou télégraphique qui ne prend pas en compte la rétroaction.", "sources": [{"documentId": "com", "page": 8, "excerpt": "B. Modèle de Shannon et Weaver (1949) : modèle télégraphique\nAbsence de rétroaction, modèle simpliste.\nC. Modèle de Jakobson (1960) : les fonctions du langage\nFonction\nRôle\nRéférentielle\nInformer\nExpressive\nÉmouvoir\nConative\nInfluencer\nPhatique\nCréer du contact\nPoétique\nJeu sur la forme\nMétalinguistique Expliquer un code\n2. Wiener et la cybernétique (1948)\n\nSystème : ensemble d'éléments interdépendants tels que la modification de l'un", "highlight": "Shannon"}]}, {"id": "communication-concept-035", "chapter": "3 · Les théories", "question": "Quelles sont les six fonctions du langage de Jakobson ?", "answer": "Référentielle, expressive, conative, phatique, poétique et métalinguistique.", "sources": [{"documentId": "com", "page": 8, "excerpt": "C. Modèle de Jakobson (1960) : les fonctions du langage\nFonction\nRôle\nRéférentielle\nInformer\nExpressive\nÉmouvoir\nConative\nInfluencer\nPhatique\nCréer du contact\nPoétique\nJeu sur la forme\nMétalinguistique Expliquer un code\n2. Wiener et la cybernétique (1948)\n\nSystème : ensemble d'éléments interdépendants tels que la modification de l'un \nentraîne celle de tous les autres.\n", "highlight": "Jakobson"}]}, {"id": "communication-concept-036", "chapter": "3 · Les théories", "question": "Qu’est-ce que la rétroaction ?", "answer": "C’est le retour d’information qui permet à un système de connaître son état et de se réguler.", "sources": [{"documentId": "com", "page": 8, "excerpt": "Absence de rétroaction, modèle simpliste.\nC. Modèle de Jakobson (1960) : les fonctions du langage\nFonction\nRôle\nRéférentielle\nInformer\nExpressive\nÉmouvoir\nConative\nInfluencer\nPhatique\nCréer du contact\nPoétique\nJeu sur la forme\nMétalinguistique Expliquer un code\n2. Wiener et la cybernétique (1948)\n\nSystème : ensemble d'éléments interdépendants tels que la modification de l'un \nentraîne celle de tous les autres.\n", "highlight": "rétroaction"}]}, {"id": "communication-concept-037", "chapter": "3 · Les théories", "question": "Qu’est-ce que la cybernétique ?", "answer": "C’est la science des communications et de la régulation dans l’être vivant et la machine.", "sources": [{"documentId": "com", "page": 8, "excerpt": "2. Wiener et la cybernétique (1948)\n\nSystème : ensemble d'éléments interdépendants tels que la modification de l'un \nentraîne celle de tous les autres.\n\nIl se régule grâce aux boucles de rétroaction (informations sur son état et celui de son \nenvironnement).\n\nUn système est ouvert car il communique sans interruption avec son \nenvironnement. Un système stable n'est pas nécessairement statique.\n", "highlight": "cybernétique"}]}, {"id": "communication-concept-038", "chapter": "3 · Les théories", "question": "Quel principe fondamental retient-on de l’école de Palo Alto ?", "answer": "On ne peut pas ne pas communiquer : les comportements et le non-verbal transmettent aussi des messages.", "sources": [{"documentId": "com", "page": 8, "excerpt": "1. On ne peut pas ne pas communiquer : même le silence, la posture ou le design \nminimaliste d'un produit envoient un message.\n2. Tout message a deux niveaux : contenu (ce qui est dit) + relation (la manière dont \nc'est dit).\n3. La communication est circulaire : système d'interactions, pas une ligne droite (ex. \npost TikTok d'une marque → commentaires → réponse → co-construction du \nmessage).", "highlight": "On ne peut pas"}]}, {"id": "communication-concept-039", "chapter": "3 · Les théories", "question": "Quels sont les deux niveaux d’un message selon Palo Alto ?", "answer": "Le contenu, c’est-à-dire ce qui est dit, et la relation, c’est-à-dire la manière dont c’est dit.", "sources": [{"documentId": "com", "page": 8, "excerpt": "2. Tout message a deux niveaux : contenu (ce qui est dit) + relation (la manière dont \nc'est dit).\n3. La communication est circulaire : système d'interactions, pas une ligne droite (ex. \npost TikTok d'une marque → commentaires → réponse → co-construction du \nmessage).\n4. Verbal et non verbal : gestes, images, couleurs véhiculent un sens aussi fort que les \nmots.", "highlight": "deux niveaux"}]}, {"id": "communication-concept-040", "chapter": "3 · Les théories", "question": "Que signifient logos, pathos et ethos ?", "answer": "Logos : persuasion par la raison et la démonstration. Pathos : persuasion par l’émotion. Ethos : persuasion par le statut et la crédibilité de l’émetteur.", "sources": [{"documentId": "com", "page": 9, "excerpt": "LOGOS\nFonctionnelle ou démonstrative : met en avant les performances du produit \nface aux problèmes du consommateur\nPATHOS\nÉmotionnelle : pulsions, motivations hédonistes, d'auto-expression, oblatives\nETHOS\nMet en avant le statut de la marque ou de l'entreprise\nb) Création d'automatismes : modèle behavioriste\n\nLes comportements sont des réponses à des stimuli du monde extérieur.\n", "highlight": "LOGOS"}]}, {"id": "communication-concept-041", "chapter": "3 · Les théories", "question": "Qu’est-ce que le modèle behavioriste ?", "answer": "Il explique les comportements comme des réponses à des stimuli extérieurs. La répétition et la nature des stimuli favorisent le conditionnement.", "sources": [{"documentId": "com", "page": 9, "excerpt": "b) Création d'automatismes : modèle behavioriste\n\nLes comportements sont des réponses à des stimuli du monde extérieur.\n\nDéveloppé par Watson, Pavlov, Bekhterev. Réponses conditionnées par la fréquence \net la nature des stimuli.\n\nInspiré des théoriciens de la propagande politique (Tchakhotine).\nc) Persuasion logique : modèle de la hiérarchie des effets\nLe comportement est le résultat d'un processus mental d'acquisition et de traitement", "highlight": "behavioriste"}]}, {"id": "communication-concept-042", "chapter": "3 · Les théories", "question": "Que signifie AIDA ?", "answer": "Attention, intérêt, désir, achat.", "sources": [{"documentId": "com", "page": 9, "excerpt": "Modèle AIDA (Lewis, 1898) : Attention → Intérêt → Désir → Achat.\nHiérarchie des effets : un consommateur ne passe pas instantanément de l'ignorance à \nl'achat. 3 niveaux, 6 étapes :\nStade\nÉtape\nDescription\nCognitif Prise de conscience Il découvre l'existence du produit ou de la marque\nConnaissance\nIl acquiert des informations\nAffectif Appréciation\nIl forme une opinion ou un ressenti positif ou négatif\nPréférence", "highlight": "AIDA"}]}, {"id": "communication-concept-043", "chapter": "3 · Les théories", "question": "Quelles sont les six étapes de la hiérarchie des effets ?", "answer": "Prise de conscience, connaissance, appréciation, préférence, conviction et achat.", "sources": [{"documentId": "com", "page": 9, "excerpt": "Cognitif Prise de conscience Il découvre l'existence du produit ou de la marque\nConnaissance\nIl acquiert des informations\nAffectif Appréciation\nIl forme une opinion ou un ressenti positif ou négatif\nPréférence\nIl compare et choisit une marque préférée\nConatif Conviction\nIl est persuadé que c'est le bon choix\nAchat\nIl agit et effectue l'achat\nUtilité : où se situe la cible ? choisir les bons canaux et contenus ; quel message selon l'étape", "highlight": "Prise de conscience"}]}, {"id": "communication-concept-044", "chapter": "3 · Les théories", "question": "Qu’est-ce que le storytelling ?", "answer": "C’est l’art de raconter une histoire pour susciter l’émotion, donner du sens et convaincre.", "sources": [{"documentId": "com", "page": 10, "excerpt": "Art de raconter des histoires à fort pouvoir de séduction et de conviction. Pour parler \nà la tête, il faut souvent d'abord toucher le cœur.\n\nContenu non promotionnel : on crée un environnement, un contexte réel ou fictif lié \nà la marque, au lieu de vanter les points forts du produit. Technique de mise en récit \nsur la base d'une structure.\n\nBut : faire connaître un nouveau produit, améliorer l'image, augmenter la notoriété,", "highlight": "Art de raconter"}]}, {"id": "communication-concept-045", "chapter": "3 · Les théories", "question": "Qu’est-ce que le two-step flow of communication ?", "answer": "C’est une diffusion de la communication en deux temps, dans laquelle les leaders d’opinion jouent un rôle de relais et d’influence.", "sources": [{"documentId": "com", "page": 10, "excerpt": "d'information, rôle d'expert, bâtisseurs de notoriété (e-réputation). Modèle du two-step \nflow of communication.\n5. Analyse sémiotique du message\n\nSémiotique : science générale des signes. Précurseurs : Peirce, de Saussure, R. \nBarthes. Étymologie d'« image » : imitari. L'image est une représentation.\n\nLe signe se décompose en signifiant et signifié. Exemples : montagne (Leroy Merlin)", "highlight": "two-step"}]}, {"id": "communication-concept-046", "chapter": "3 · Les théories", "question": "Qu’est-ce que la sémiotique ?", "answer": "C’est la science générale des signes.", "sources": [{"documentId": "com", "page": 10, "excerpt": "5. Analyse sémiotique du message\n\nSémiotique : science générale des signes. Précurseurs : Peirce, de Saussure, R. \nBarthes. Étymologie d'« image » : imitari. L'image est une représentation.\n\nLe signe se décompose en signifiant et signifié. Exemples : montagne (Leroy Merlin) \n= nature, liberté, air pur ; colombe = amour, espérance, paix.\n\nLa relation signifiant / signifié est implicite ou explicite. Si elle est trop subjective,", "highlight": "sémiotique"}]}, {"id": "communication-concept-047", "chapter": "3 · Les théories", "question": "Quelle différence y a-t-il entre signifiant et signifié ?", "answer": "Le signifiant est la forme perceptible du signe. Le signifié est le sens ou le concept qui lui est associé.", "sources": [{"documentId": "com", "page": 10, "excerpt": "Le signe se décompose en signifiant et signifié. Exemples : montagne (Leroy Merlin) \n= nature, liberté, air pur ; colombe = amour, espérance, paix.\n\nLa relation signifiant / signifié est implicite ou explicite. Si elle est trop subjective, \nrisque de mauvaise interprétation. Un signe peut \nêtre monosémique ou polysémique.\n\nDénotation : le signifié est construit en tant que tel. Connotation : valeur subjective", "highlight": "signifiant"}]}, {"id": "communication-concept-048", "chapter": "3 · Les théories", "question": "Quelle différence y a-t-il entre dénotation et connotation ?", "answer": "La dénotation correspond au sens directement décrit. La connotation renvoie aux significations et valeurs subjectives associées au signe.", "sources": [{"documentId": "com", "page": 10, "excerpt": "Dénotation : le signifié est construit en tant que tel. Connotation : valeur subjective \nliée au signe du fait de sa forme ou fonction.\nCas Pepsi (bad buzz) : signifiés imaginés = unité, rapprochement, paix ; perçu = banalisation \ndes protestations et des violences policières.\nConclusion : plus un signe est polysémique, subjectif et culturellement chargé, \nplus le risque d'interprétation divergente augmente.", "highlight": "Dénotation"}]}, {"id": "communication-concept-049", "chapter": "3 · Les théories", "question": "Qu’est-ce qu’un signe polysémique ?", "answer": "C’est un signe qui peut recevoir plusieurs significations ou interprétations.", "sources": [{"documentId": "com", "page": 10, "excerpt": "être monosémique ou polysémique.\n\nDénotation : le signifié est construit en tant que tel. Connotation : valeur subjective \nliée au signe du fait de sa forme ou fonction.\nCas Pepsi (bad buzz) : signifiés imaginés = unité, rapprochement, paix ; perçu = banalisation \ndes protestations et des violences policières.\nConclusion : plus un signe est polysémique, subjectif et culturellement chargé, \nplus le risque d'interprétation divergente augmente.", "highlight": "polysémique"}]}, {"id": "communication-concept-050", "chapter": "3 · Les théories", "question": "Qu’est-ce qu’une cascade de propagation ?", "answer": "C’est une diffusion dans laquelle chaque personne transmet l’information à plusieurs autres, qui la retransmettent à leur tour.", "sources": [{"documentId": "com", "page": 4, "excerpt": "Cascade de propagation\nElle se produit lorsqu'on donne l'information à plusieurs personnes à la fois et que chacune \nla propage ensuite à plusieurs autres.\nExpériences\n\nGeste\n\nDessin\n\nParole\nÀ retenir : une rumeur se déforme selon les préjugés de ceux qui la relaient.", "highlight": "Cascade"}]}, {"id": "communication-concept-051", "chapter": "3 · Les théories", "question": "Pourquoi une rumeur peut-elle se déformer ?", "answer": "Les préjugés et la culture des personnes qui transmettent l’information peuvent orienter sa sélection, sa transformation et son amplification.", "sources": [{"documentId": "com", "page": 4, "excerpt": "La distorsion de l'information n'est pas aléatoire.\n\nLa déformation reflète nos préjugés et notre culture.\n\nChaque groupe construit la vérité qu'il veut entendre.\nDifférentes chaînes de transmission\nChaîne\nCe qui se passe\nEffet\nInformation transmise à des \npersonnes qui ont déjà des préjugés \nnégatifs\nElle prend de plus en plus \nd'ampleur : tout le monde entend \nl'info et y croit\nMessage de plus en \nplus alarmant\nInformation transmise à des", "highlight": "distorsion"}]}, {"id": "communication-concept-052", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de l’ARPP ?", "answer": "L’Autorité de régulation professionnelle de la publicité participe à l’autorégulation de la publicité et formule des recommandations.", "sources": [{"documentId": "com", "page": 10, "excerpt": "ARPP (Autorité de régulation \nprofessionnelle de la publicité)\nAutorégulation : délivre des recommandations et", "highlight": "ARPP"}]}, {"id": "communication-concept-053", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de l’ARCOM ?", "answer": "Elle régule les médias audiovisuels.", "sources": [{"documentId": "com", "page": 11, "excerpt": "CSA / ARCOM\nRégule les médias audiovisuels\nCNIL\nEncadre la collecte et l'utilisation des données \npersonnelles\nDGCCRF\nLutte contre les pratiques commerciales \ntrompeuses\nEn Europe\n\nDirectives européennes (ex. directive 2005/29/CE sur les pratiques commerciales \ndéloyales).\n\nEncadrement du numérique avec le RGPD (Règlement général sur la protection des \ndonnées, 2018). Ex. : Facebook condamné à plusieurs reprises en Europe pour non-", "highlight": "ARCOM"}]}, {"id": "communication-concept-054", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de la CNIL ?", "answer": "Elle veille à la protection des données personnelles et encadre leur collecte et leur utilisation.", "sources": [{"documentId": "com", "page": 11, "excerpt": "CNIL\nEncadre la collecte et l'utilisation des données \npersonnelles\nDGCCRF\nLutte contre les pratiques commerciales \ntrompeuses\nEn Europe\n\nDirectives européennes (ex. directive 2005/29/CE sur les pratiques commerciales \ndéloyales).\n\nEncadrement du numérique avec le RGPD (Règlement général sur la protection des \ndonnées, 2018). Ex. : Facebook condamné à plusieurs reprises en Europe pour non-\nrespect du RGPD.", "highlight": "CNIL"}]}, {"id": "communication-concept-055", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de la DGCCRF ?", "answer": "Elle lutte notamment contre les pratiques commerciales trompeuses.", "sources": [{"documentId": "com", "page": 11, "excerpt": "DGCCRF\nLutte contre les pratiques commerciales \ntrompeuses\nEn Europe\n\nDirectives européennes (ex. directive 2005/29/CE sur les pratiques commerciales \ndéloyales).\n\nEncadrement du numérique avec le RGPD (Règlement général sur la protection des \ndonnées, 2018). Ex. : Facebook condamné à plusieurs reprises en Europe pour non-\nrespect du RGPD.\n2. Les grandes règles encadrant la publicité\na) Publicité trompeuse ou mensongère", "highlight": "DGCCRF"}]}, {"id": "communication-concept-056", "chapter": "4 · Éthique et réglementation", "question": "Qu’est-ce qu’une publicité trompeuse ?", "answer": "C’est une publicité qui induit le consommateur en erreur, notamment sur le prix, la qualité ou les caractéristiques de l’offre.", "sources": [{"documentId": "com", "page": 11, "excerpt": "trompeuses\nEn Europe\n\nDirectives européennes (ex. directive 2005/29/CE sur les pratiques commerciales \ndéloyales).\n\nEncadrement du numérique avec le RGPD (Règlement général sur la protection des \ndonnées, 2018). Ex. : Facebook condamné à plusieurs reprises en Europe pour non-\nrespect du RGPD.\n2. Les grandes règles encadrant la publicité\na) Publicité trompeuse ou mensongère", "highlight": "trompeuse"}]}, {"id": "communication-concept-057", "chapter": "4 · Éthique et réglementation", "question": "Qu’est-ce qu’une publicité comparative ?", "answer": "C’est une publicité qui identifie explicitement ou implicitement un concurrent ou les biens et services qu’il propose.", "sources": [{"documentId": "com", "page": 11, "excerpt": "b) Publicité comparative\n\nDéfinition : toute publicité qui, explicitement ou implicitement, identifie un \nconcurrent ou les biens / services qu'il offre.\n\nLongtemps non interdite, mais la jurisprudence la rendait impossible. Loi de \n1992 : elle l'autorise si elle est loyale, véridique et permet une comparaison \nvérifiable et objective.\nPOUR\nCONTRE\nS'aligner sur les pays occidentaux\nRelève souvent du dénigrement", "highlight": "comparative"}]}, {"id": "communication-concept-058", "chapter": "4 · Éthique et réglementation", "question": "Que signifie RGPD ?", "answer": "Règlement général sur la protection des données. Il encadre la protection des données personnelles.", "sources": [{"documentId": "com", "page": 11, "excerpt": "Encadrement du numérique avec le RGPD (Règlement général sur la protection des \ndonnées, 2018). Ex. : Facebook condamné à plusieurs reprises en Europe pour non-\nrespect du RGPD.\n2. Les grandes règles encadrant la publicité\na) Publicité trompeuse ou mensongère\nInterdite : ne pas induire le consommateur en erreur (prix, qualité, caractéristiques). Ex. : \npublicité mensongère de Volkswagen sur les émissions polluantes.\nb) Publicité comparative\n", "highlight": "RGPD"}]}, {"id": "communication-concept-059", "chapter": "4 · Éthique et réglementation", "question": "Qu’est-ce que la communication éthique ?", "answer": "C’est une communication responsable qui tient compte de ses effets et respecte les publics auxquels elle s’adresse.", "sources": [{"documentId": "com", "page": 12, "excerpt": "3. L'éthique de la communication commerciale\nSujet\nDéfinition\nExemple\nStéréotypes et \nreprésentation sociale\nRisque de sexisme, \nracisme, grossophobie\nH&M 2018 : enfant noir portant un \nsweat « coolest monkey in the jungle » \n→ accusation de racisme, boycott \nmassif\nGreenwashing / social \nwashing\nPrétendre être écologique \nou engagé sans réelle \naction\nTotalEnergies accusé de greenwashing \ndans ses pubs sur la transition \nénergétique", "highlight": "éthique"}]}, {"id": "communication-concept-060", "chapter": "5 · L’image de marque", "question": "Quelle différence y a-t-il entre identité, image et réputation de marque ?", "answer": "L’identité est ce que la marque veut exprimer. L’image est la représentation que les publics se font d’elle. La réputation se construit dans la durée à partir des opinions et expériences.", "sources": [{"documentId": "com", "page": 13, "excerpt": "Identité de \nmarque\nCe que la marque veut dire d'elle-\nmême : son ADN, sa mission, ses \nvaleurs\nDecathlon : « rendre le sport \naccessible à tous »\nImage de \nmarque\nCe que les consommateurs perçoivent \nréellement : la représentation mentale \nqu'ils s'en font\nTesla veut incarner l'innovation \ndurable, mais certains perçoivent une \nimage liée à Elon Musk\nRéputation\nL'image dans la durée, façonnée par \nl'expérience, le bouche-à-oreille, les \nmédias", "highlight": "Identité de"}]}, {"id": "communication-concept-061", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la personnalité de marque ?", "answer": "C’est l’ensemble des caractéristiques humaines associées à une marque.", "sources": [{"documentId": "com", "page": 13, "excerpt": "b) Personnalité de marque (Aaker, 1997) : 5 dimensions\nDimension\nTraits associés\nExemples\nSincérité\nHonnêteté, proximité, chaleur, simplicité, \nbienveillance. Marques humaines et \naccessibles, relation de confiance et \nd'authenticité\nDisney (valeurs familiales, magie \nde l'enfance), Innocent\nExcitation\nÉnergie, audace, créativité, modernité, \njeunesse. Marques qui stimulent et \nsurprennent\nRed Bull (sports extrêmes, \ndépassement de soi), TikTok", "highlight": "Personnalité de marque"}]}, {"id": "communication-concept-062", "chapter": "5 · L’image de marque", "question": "Quelles sont les cinq dimensions de la personnalité de marque selon Aaker ?", "answer": "Sincérité, excitation, compétence, sophistication et robustesse.", "sources": [{"documentId": "com", "page": 13, "excerpt": "b) Personnalité de marque (Aaker, 1997) : 5 dimensions\nDimension\nTraits associés\nExemples\nSincérité\nHonnêteté, proximité, chaleur, simplicité, \nbienveillance. Marques humaines et \naccessibles, relation de confiance et \nd'authenticité\nDisney (valeurs familiales, magie \nde l'enfance), Innocent\nExcitation\nÉnergie, audace, créativité, modernité, \njeunesse. Marques qui stimulent et \nsurprennent\nRed Bull (sports extrêmes, \ndépassement de soi), TikTok", "highlight": "Aaker"}]}, {"id": "communication-concept-063", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que le capital marque selon Keller ?", "answer": "C’est la valeur liée à ce que les consommateurs pensent, ressentent et croient au sujet de la marque, au-delà de la qualité réelle du produit.", "sources": [{"documentId": "com", "page": 14, "excerpt": "Le capital-marque (brand equity)\nKeller (1993) : CBBE (Customer Based Brand Equity)\n\nLe pouvoir d'une marque ne dépend pas seulement de sa qualité réelle ou de son \nbudget publicitaire, mais de ce que les consommateurs pensent, ressentent et \ncroient à son sujet.\n\n« Une marque forte se construit dans la tête et le cœur des consommateurs. » Pour \nKeller, l'image de marque est une ressource.\nLa pyramide de Keller, 4 étages :\nÉtage\nDéfinition", "highlight": "capital-marque"}]}, {"id": "communication-concept-064", "chapter": "5 · L’image de marque", "question": "Quels sont les quatre niveaux de la pyramide de Keller ?", "answer": "Notoriété, associations, réponse et résonance.", "sources": [{"documentId": "com", "page": 14, "excerpt": "1. NOTORIÉTÉ\nMarque connue et reconnue. Reconnaissance : « je la reconnais quand je \nla vois ». Rappel spontané : « je la cite sans aide ». Objectif : la marque \nvient naturellement à l'esprit en situation d'achat\n2. \nASSOCIATIONS\nImage mentale de la marque. Associations de \nperformance (fonctionnel : qualité, fiabilité, design, innovation, service ; \nex. Toyota = fiabilité). Associations symboliques /", "highlight": "NOTORIÉTÉ"}]}, {"id": "communication-concept-065", "chapter": "5 · L’image de marque", "question": "Quelles sont les deux grandes catégories d’associations à la marque ?", "answer": "Les associations de performance, liées aux qualités fonctionnelles, et les associations symboliques, liées aux valeurs, au style de vie et à la personnalité.", "sources": [{"documentId": "com", "page": 14, "excerpt": "performance (fonctionnel : qualité, fiabilité, design, innovation, service ; \nex. Toyota = fiabilité). Associations symboliques / \nimaginaires (émotionnel : valeurs, style de vie, personnalité ; ex. Nike = \nperformance et dépassement de soi). C'est ici que se forment les valeurs \net l'univers symbolique\n3. RÉPONSE\nRéactions des consommateurs. Jugement (rationnel : qualité, crédibilité,", "highlight": "performance"}]}, {"id": "communication-concept-066", "chapter": "5 · L’image de marque", "question": "Quelle différence y a-t-il entre jugements et sentiments envers une marque ?", "answer": "Les jugements sont des évaluations rationnelles, notamment de qualité et de crédibilité. Les sentiments sont les réactions affectives suscitées par la marque.", "sources": [{"documentId": "com", "page": 14, "excerpt": "Réactions des consommateurs. Jugement (rationnel : qualité, crédibilité, \nconsidération, supériorité ; ex. Apple jugée innovante et haut de \ngamme). Sentiments (émotionnels : sécurité, plaisir, fierté, excitation, \nnostalgie…)\n4. RÉSONANCE\nRelation forte, durable et affective. Fidélité comportementale (achats \nrépétés), attachement affectif(« la marque fait partie de moi \n»), sentiment d'appartenance (communauté forte), engagement", "highlight": "Jugement"}]}, {"id": "communication-concept-067", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la résonance de marque ?", "answer": "C’est une relation forte et durable avec la marque, qui combine fidélité comportementale, attachement affectif, appartenance et engagement actif.", "sources": [{"documentId": "com", "page": 14, "excerpt": "4. RÉSONANCE\nRelation forte, durable et affective. Fidélité comportementale (achats \nrépétés), attachement affectif(« la marque fait partie de moi \n»), sentiment d'appartenance (communauté forte), engagement \nactif(ambassadeurs). Ex. : clubs et tatouages Harley-Davidson, fans \nd'Apple qui font la queue\nUtilité du modèle : diagnostiquer à quel niveau se situe la marque et planifier des actions \nadaptées à chaque étape :\n1. Campagne de notoriété", "highlight": "RÉSONANCE"}]}, {"id": "communication-concept-068", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la dissonance entre identité et image de marque ?", "answer": "C’est un décalage entre ce que la marque veut exprimer et la façon dont elle est réellement perçue.", "sources": [{"documentId": "com", "page": 15, "excerpt": "Dissonance\nDécalage entre \nidentité voulue et \nimage perçue\nMcDonald's veut se \nrepositionner sur une image \nplus équilibrée et moderne, \nmais reste perçu comme fast-\nfood gras, industriel, riche en \nsucre et en sel → tentative \nperçue comme superficielle \nvoire hypocrite\nUne marque ne peut pas \nchanger son \nimage uniquement par \nla communication : il \nfaut changer les 4P pour \nêtre cohérent\nBad buzz\nErreur de \ncommunication \nvirale", "highlight": "Dissonance"}]}, {"id": "communication-concept-069", "chapter": "5 · L’image de marque", "question": "Qu’est-ce qu’un bad buzz ?", "answer": "C’est la propagation rapide de réactions négatives qui peut dégrader l’image et la réputation d’une marque.", "sources": [{"documentId": "com", "page": 15, "excerpt": "Bad buzz\nErreur de \ncommunication \nvirale\nMarque italienne, 2018 : vidéos \nInstagram d'une Chinoise \nmangeant un plat italien avec \ndes baguettes. Intention : \nhumour sur le choc culturel. \nRéception : racisme, \ncondescendance, stéréotypes. \nConséquences : boycott, \nannulation du défilé, excuses \ntardives jugées peu sincères\nComprendre les \ndifférences culturelles \navant de communiquer, \nsurtout à l'ère des réseaux \nsociaux\nGreenwashing /", "highlight": "Bad buzz"}]}, {"id": "communication-concept-070", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que le greenwashing ou le social washing ?", "answer": "C’est le fait de revendiquer des engagements environnementaux ou sociaux peu sincères, trompeurs ou insuffisamment soutenus par les pratiques réelles.", "sources": [{"documentId": "com", "page": 15, "excerpt": "Greenwashing / \nsocial washing\nCommuniquer sur \ndes valeurs \néthiques sans les \nappliquer\nH&M et la « Conscious \ncollection » : gamme censée \nêtre durable, étiquettes \nécologiques trompeuses → \nbaisse de crédibilité\nActions réelles et \nmesurables\nLe partiel : informations pratiques\n\nNe pas être en retard ; rentrer par le bas.\n\nDurée : 1h30.\n\nQuelques questions de cours. Pas besoin de définitions apprises par cœur, tant que la", "highlight": "washing"}]}], "documents": ["com"]}];
